const TRIVIA_MONTHS = {
  en: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
  bn: ["জানুয়ারি", "ফেব্রুয়ারি", "মার্চ", "এপ্রিল", "মে", "জুন", "জুলাই", "আগস্ট", "সেপ্টেম্বর", "অক্টোবর", "নভেম্বর", "ডিসেম্বর"],
};
const TRIVIA_BN_ORD = ["১ম", "২য়", "৩য়", "৪র্থ", "৫ম", "৬ষ্ঠ", "৭ম", "৮ম", "৯ম", "১০ম", "১১তম", "১২তম"];
const TRIVIA_EN_ORD = ["1st", "2nd", "3rd", "4th", "5th", "6th", "7th", "8th", "9th", "10th", "11th", "12th"];
function triviaBnNum(n) { return String(n).replace(/[0-9]/g, (d) => "০১২৩৪৫৬৭৮৯"[Number(d)]); }
function triviaRnd(lo, hi) { return crypto.randomInt(lo, hi + 1); }
function triviaPickOthers(list, exclude, k) {
  const pool = list.filter((x) => x !== exclude);
  const out = [];
  while (out.length < k && pool.length) out.push(pool.splice(crypto.randomInt(0, pool.length), 1)[0]);
  return out;
}
// three different wrong numbers near the right one
function triviaNearNumbers(ans, spread) {
  const set = new Set();
  let guard = 0;
  while (set.size < 3 && guard++ < 100) {
    const d = triviaRnd(1, spread) * (crypto.randomInt(0, 2) ? 1 : -1);
    const v = ans + d;
    if (v !== ans && v >= 0) set.add(v);
  }
  return [...set];
}
function triviaGenMath(lang) {
  const kind = triviaRnd(0, 4);
  let q;
  let ans;
  let spread = 10;
  if (kind === 0) { const a = triviaRnd(12, 99); const b = triviaRnd(12, 99); ans = a + b; q = [a, "+", b]; }
  else if (kind === 1) { const a = triviaRnd(40, 150); const b = triviaRnd(11, a - 5); ans = a - b; q = [a, "−", b]; }
  else if (kind === 2) { const a = triviaRnd(3, 19); const b = triviaRnd(3, 19); ans = a * b; q = [a, "×", b]; spread = Math.max(6, Math.round(ans / 8)); }
  else if (kind === 3) { const b = triviaRnd(2, 12); ans = triviaRnd(3, 15); const a = ans * b; q = [a, "÷", b]; spread = 4; }
  else {
    // sequence: start, step → next number
    const start = triviaRnd(1, 20); const step = triviaRnd(2, 9);
    const seq = [0, 1, 2, 3].map((i) => start + i * step);
    ans = start + 4 * step;
    const f = (n) => (lang === "bn" ? triviaBnNum(n) : String(n));
    return {
      id: `g_seq_${start}_${step}`, q: lang === "bn" ? `পরের সংখ্যাটি কত? ${seq.map(f).join(", ")}, ?` : `What comes next? ${seq.join(", ")}, ?`,
      a: f(ans), wrong: triviaNearNumbers(ans, step + 2).map(f),
    };
  }
  const f = (n) => (lang === "bn" ? triviaBnNum(n) : String(n));
  return {
    id: `g_m_${q.join("")}`, q: lang === "bn" ? `${f(q[0])} ${q[1]} ${f(q[2])} = কত?` : `What is ${q[0]} ${q[1]} ${q[2]}?`,
    a: f(ans), wrong: triviaNearNumbers(ans, spread).map(f),
  };
}
function triviaGenCapital(lang) {
  const c = TRIVIA_COUNTRIES[crypto.randomInt(0, TRIVIA_COUNTRIES.length)];
  const L = lang === "bn" ? 2 : 0;
  const caps = TRIVIA_COUNTRIES.map((x) => x[L + 1]);
  const names = TRIVIA_COUNTRIES.map((x) => x[L]);
  if (crypto.randomInt(0, 2)) {
    return {
      id: `g_cap_${c[0]}`, q: lang === "bn" ? `${c[2]}-এর রাজধানীর নাম কী?` : `What is the capital of ${c[0]}?`,
      a: c[L + 1], wrong: triviaPickOthers(caps, c[L + 1], 3),
    };
  }
  return {
    id: `g_cty_${c[0]}`, q: lang === "bn" ? `${c[3]} কোন দেশের রাজধানী?` : `${c[1]} is the capital of which country?`,
    a: c[L], wrong: triviaPickOthers(names, c[L], 3),
  };
}
function triviaGenMonth(lang) {
  const i = crypto.randomInt(0, 12);
  const m = TRIVIA_MONTHS[lang === "bn" ? "bn" : "en"];
  return {
    id: `g_mon_${i}`, q: lang === "bn" ? `ইংরেজি বছরের ${TRIVIA_BN_ORD[i]} মাস কোনটি?` : `Which is the ${TRIVIA_EN_ORD[i]} month of the year?`,
    a: m[i], wrong: triviaPickOthers(m, m[i], 3),
  };
}
function triviaGenerate(lang) {
  const r = crypto.randomInt(0, 10);
  if (r < 4) return triviaGenCapital(lang);
  if (r < 9) return triviaGenMath(lang);
  return triviaGenMonth(lang);
}
// English questions from Open Trivia DB (thousands of checked multiple-choice
// questions, free). Any problem → [] and the game uses our own questions.
async function triviaFetchOpenTdb(n) {
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 4000);
    const res = await fetch(`https://opentdb.com/api.php?amount=${n}&type=multiple&encode=url3986`, { signal: ctrl.signal });
    clearTimeout(timer);
    if (!res.ok) return [];
    const j = await res.json();
    if (!j || j.response_code !== 0 || !Array.isArray(j.results)) return [];
    const dec = (s) => { try { return decodeURIComponent(String(s || "")); } catch (e) { return String(s || ""); } };
    return j.results.map((r) => ({
      id: `otdb_${crypto.createHash("sha1").update(dec(r.question)).digest("hex").slice(0, 12)}`,
      q: dec(r.question), a: dec(r.correct_answer), wrong: (r.incorrect_answers || []).map(dec).slice(0, 3),
    })).filter((x) => x.q && x.a && x.wrong.length === 3 && x.q.length <= 220);
  } catch (e) {
    return [];
  }
}

// One game's questions: our own list (+ miglife's own questions) mixed with freshly
// made ones — for English also live questions from Open Trivia DB — so games
// practically never run out or repeat.
async function triviaPickQuestions(lang, n) {
  const pool = (TRIVIA_BANK[lang] || TRIVIA_BANK.en).map(([q, a, wrong], i) => ({ id: `${lang}${i}`, q, a, wrong }));
  try {
    const extra = await db.collection("trivia_questions").where("lang", "==", lang).where("active", "==", true).limit(500).get();
    extra.docs.forEach((d) => {
      const q = String(d.get("q") || "").trim();
      const a = String(d.get("a") || "").trim();
      const wrong = (d.get("wrong") || []).map((x) => String(x || "").trim()).filter(Boolean).slice(0, 3);
      if (q && a && wrong.length === 3) pool.push({ id: `x_${d.id}`, q, a, wrong });
    });
  } catch (e) { /* built-in questions are enough */ }
  const recentRef = db.collection("_operations").doc(`trivia_recent_${lang}`);
  const recent = new Set(((await recentRef.get()).get("ids") || []));
  let fresh = pool.filter((p) => !recent.has(p.id));
  if (fresh.length < n) fresh = pool;

  const fromList = lang === "bn" ? 5 : 3;
  const fromWeb = lang === "en" ? await triviaFetchOpenTdb(5) : [];
  const chosen = [...fromWeb, ...triviaShuffle(fresh).slice(0, fromList)];
  const seen = new Set(chosen.map((c) => c.id));
  let guard = 0;
  while (chosen.length < n && guard++ < 200) {
    const g = triviaGenerate(lang);
    if (seen.has(g.id) || g.wrong.length !== 3 || new Set([g.a, ...g.wrong]).size !== 4) continue;
    seen.add(g.id);
    chosen.push(g);
  }
  const listIds = chosen.filter((c) => pool.some((p) => p.id === c.id)).map((c) => c.id);
  const keep = Math.max(0, Math.min(pool.length - n, 50));
  await recentRef.set({ ids: [...listIds, ...recent].slice(0, keep) });
  return triviaShuffle(chosen).slice(0, n).map((p) => {
    const options = triviaShuffle([p.a, ...p.wrong]);
    return { id: p.id, q: p.q, options, correct: options.indexOf(p.a) };
  });
}
function triviaIsStaff(userSnap) {
  const role = normalizeUsername(userSnap.get("role"));
  return isMainFounderName(userSnap.get("username")) || ["admin", "staff", "superadmin"].includes(role);
}
function triviaLangName(lang) { return lang === "bn" ? "বাংলা" : "English"; }
// faster right answers score more (7-second questions)
function triviaPtsFor(elapsedMs) { return elapsedMs <= 3_000 ? 10 : (elapsedMs <= 5_000 ? 7 : 5); }
function triviaOptionsLine(options) { return options.map((o, i) => `${TRIVIA_LETTERS[i]}) ${o}`).join("   "); }

exports.triviaStart = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const lang = String((data && data.lang) || "en") === "bn" ? "bn" : "en";
  const roomId = triviaRoomOf(data && data.roomId);
  // outside the 🧠 Trivia room it runs only where /bot trivia is ON
  if (roomId !== TRIVIA_ROOM) {
    const b = await roomBotsRef(roomId).get();
    if (!b.exists || b.get("bot") !== "trivia") {
      throw new E("failed-precondition", "Trivia Bot is not on in this room — type /bot trivia first.");
    }
  }
  const me = await db.collection("users").doc(uid).get();
  const name = String(me.get("username") || "Player");
  const questions = await triviaPickQuestions(lang, TRIVIA_QUESTIONS_PER_GAME);
  return db.runTransaction(async (tx) => {
    const g = await tx.get(triviaRef(roomId));
    const now = Date.now();
    if (g.exists && g.get("running") === true && now - Number(g.get("updatedAtMs") || 0) < TRIVIA_STALE_MS) {
      throw new E("failed-precondition", "A trivia game is already running.");
    }
    const round = Number((g.exists && g.get("roundNumber")) || 0) + 1;
    questions.forEach((q, i) => tx.set(triviaSecretRef(roomId, round, i + 1), {
      q: q.q, options: q.options, correct: q.correct, lang, right: {}, createdAt: FieldValue.serverTimestamp(),
    }));
    const first = questions[0];
    tx.set(triviaRef(roomId), {
      game: "trivia", running: true, phase: "QUESTION", lang, roundNumber: round,
      qNo: 1, total: questions.length, question: first.q, options: first.options,
      askedAt: now, phaseEndsAt: now + TRIVIA_QUESTION_MS, answered: {}, answeredCount: 0,
      correctIndex: -1, lastRight: [],
      startedBy: name, startedByUid: uid, scores: {},
      updatedAtMs: now, updatedAt: FieldValue.serverTimestamp(),
    });
    triviaSay(tx, roomId, [
      `🧠 ${name} started Trivia (${triviaLangName(lang)}) — ${questions.length} questions! Tap A · B · C · D (or type a / b / c / d). One answer each — faster right answers score more.${roomId === TRIVIA_ROOM ? "" : " · !stop to end"}`,
      `❓ Q1/${questions.length}: ${first.q}\n${triviaOptionsLine(first.options)}`,
    ], now);
    return { ok: true, round };
  });
});

exports.triviaAnswer = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const roomId = triviaRoomOf(data && data.roomId);
  const choice = Number(data && data.choice);
  const qNoAsked = Number(data && data.qNo);
  if (!Number.isInteger(choice) || choice < 0 || choice > 3) {
    throw new functionsV1.https.HttpsError("invalid-argument", "Pick A, B, C or D.");
  }
  const me = await db.collection("users").doc(uid).get();
  const name = String(me.get("username") || "Player");
  return db.runTransaction(async (tx) => {
    const g = await tx.get(triviaRef(roomId));
    if (!g.exists || g.get("running") !== true || g.get("phase") !== "QUESTION") return { ok: false, closed: true };
    const now = Date.now();
    const qNo = Number(g.get("qNo") || 0);
    if (Number.isFinite(qNoAsked) && qNoAsked > 0 && qNoAsked !== qNo) return { ok: false, closed: true };
    if (now > Number(g.get("phaseEndsAt") || 0)) return { ok: false, closed: true };
    const answered = g.get("answered") || {};
    if (answered[uid]) return { ok: false, already: true };
    const round = Number(g.get("roundNumber") || 0);
    const secretRef = triviaSecretRef(roomId, round, qNo);
    const secret = await tx.get(secretRef);
    if (!secret.exists) return { ok: false };
    // the result stays secret until the question closes — the phone only learns "saved"
    if (choice === Number(secret.get("correct"))) {
      const pts = triviaPtsFor(now - Number(g.get("askedAt") || now));
      tx.update(secretRef, { [`right.${uid}`]: { name, pts, at: now } });
    }
    tx.update(triviaRef(roomId), {
      [`answered.${uid}`]: true, answeredCount: FieldValue.increment(1),
      updatedAtMs: now,
    });
    return { ok: true, saved: true };
  });
});

// Closes the question (reveal + points) / next question / game over — whichever is due.
exports.triviaTick = functionsV1.https.onCall(async (data, context) => {
  requireAuth(context);
  const roomId = triviaRoomOf(data && data.roomId);
  const dayKey = dhakaDateKey();
  return db.runTransaction(async (tx) => {
    const g = await tx.get(triviaRef(roomId));
    if (!g.exists || g.get("running") !== true) return { ok: true };
    const now = Date.now();
    const round = Number(g.get("roundNumber") || 0);
    const qNo = Number(g.get("qNo") || 0);
    const total = Number(g.get("total") || TRIVIA_QUESTIONS_PER_GAME);
    const phase = g.get("phase");
    if (now - Number(g.get("updatedAtMs") || 0) > TRIVIA_STALE_MS) {
      tx.update(triviaRef(roomId), { running: false, phase: "IDLE", updatedAtMs: now });
      return { ok: true };
    }
    if (phase === "QUESTION" && now >= Number(g.get("phaseEndsAt") || 0)) {
      const secret = await tx.get(triviaSecretRef(roomId, round, qNo));
      const options = (secret.exists && secret.get("options")) || [];
      const correct = Number((secret.exists && secret.get("correct")) ?? -1);
      const right = Object.entries((secret.exists && secret.get("right")) || {})
        .map(([u, v]) => ({ uid: u, name: String(v.name || ""), pts: Number(v.pts || 0), at: Number(v.at || 0) }))
        .sort((a, b) => a.at - b.at);
      // read every winner's score docs first (transactions: reads before writes)
      const refs = right.map((r) => [
        db.collection("trivia_scores").doc(r.uid),
        db.collection("trivia_daily").doc(dayKey).collection("users").doc(r.uid),
      ]);
      const snaps = await Promise.all(refs.flat().map((ref) => tx.get(ref)));
      const scores = g.get("scores") || {};
      right.forEach((r, i) => {
        const [scoreRef, dayRef] = refs[i];
        const scoreSnap = snaps[i * 2];
        const daySnap = snaps[i * 2 + 1];
        const cur = scores[r.uid] || { name: r.name, pts: 0 };
        scores[r.uid] = { name: r.name, pts: Number(cur.pts || 0) + r.pts };
        tx.set(scoreRef, {
          username: r.name, total: Number((scoreSnap.exists && scoreSnap.get("total")) || 0) + r.pts,
          correct: Number((scoreSnap.exists && scoreSnap.get("correct")) || 0) + 1,
          updatedAt: FieldValue.serverTimestamp(),
        }, { merge: true });
        tx.set(dayRef, {
          username: r.name, pts: Number((daySnap.exists && daySnap.get("pts")) || 0) + r.pts,
          updatedAt: FieldValue.serverTimestamp(),
        }, { merge: true });
      });
      const letter = TRIVIA_LETTERS[correct] || "?";
      const answerText = options[correct] || "?";
      const who = right.length
        ? right.slice(0, 8).map((r) => `${r.name} +${r.pts}`).join(", ") + (right.length > 8 ? ` +${right.length - 8} more` : "")
        : "Nobody got it.";
      tx.update(triviaRef(roomId), {
        phase: "BREAK", phaseEndsAt: now + TRIVIA_BREAK_MS, scores,
        correctIndex: correct, lastRight: right.slice(0, 20).map((r) => ({ name: r.name, pts: r.pts })),
        updatedAtMs: now, updatedAt: FieldValue.serverTimestamp(),
      });
      triviaSay(tx, roomId, [`✅ Answer: ${letter}) ${answerText}  —  ${who}`], now);
      return { ok: true };
    }
    if (phase === "BREAK" && now >= Number(g.get("phaseEndsAt") || 0)) {
      if (qNo >= total) {
        const ranked = Object.values(g.get("scores") || {}).sort((a, b) => b.pts - a.pts);
        const medals = ["🥇", "🥈", "🥉"];
        const line = ranked.length
          ? ranked.slice(0, 5).map((s, i) => `${medals[i] || `${i + 1}.`} ${s.name} ${s.pts}`).join("  ·  ")
          : "Nobody scored this time.";
        tx.update(triviaRef(roomId), { running: false, phase: "IDLE", question: "", options: [], updatedAtMs: now, updatedAt: FieldValue.serverTimestamp() });
        triviaSay(tx, roomId, [`🏁 Trivia over! ${line}`, (roomId === TRIVIA_ROOM
          ? "Type !start bn (বাংলা) or !start en (English) to play again · !top for the leaderboard"
          : "Type !start bn (বাংলা) or !start en (English) to play again · !top for the leaderboard · /bot stop to switch the bot off")], now);
        return { ok: true };
      }
      const next = await tx.get(triviaSecretRef(roomId, round, qNo + 1));
      if (!next.exists) {
        tx.update(triviaRef(roomId), { running: false, phase: "IDLE", updatedAtMs: now });
        return { ok: true };
      }
      const options = next.get("options") || [];
      tx.update(triviaRef(roomId), {
        phase: "QUESTION", qNo: qNo + 1, question: String(next.get("q") || ""), options,
        askedAt: now, phaseEndsAt: now + TRIVIA_QUESTION_MS, answered: {}, answeredCount: 0,
        correctIndex: -1, lastRight: [], updatedAtMs: now, updatedAt: FieldValue.serverTimestamp(),
      });
      triviaSay(tx, roomId, [`❓ Q${qNo + 1}/${total}: ${next.get("q")}\n${triviaOptionsLine(options)}`], now);
    }
    return { ok: true };
  });
});

exports.triviaStop = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const roomId = triviaRoomOf(data && data.roomId);
  const me = await db.collection("users").doc(uid).get();
  // the room's owner / moderators may stop it too
  let roomBoss = false;
  try {
    const room = await db.collection("rooms").doc(roomId).get();
    const myName = normalizeUsername(me.get("username"));
    roomBoss = room.exists && (room.get("ownerUid") === uid ||
      normalizeUsername(room.get("ownerName")) === myName);
  } catch (e) { roomBoss = false; }
  return db.runTransaction(async (tx) => {
    const g = await tx.get(triviaRef(roomId));
    if (!g.exists || g.get("running") !== true) return { ok: true };
    if (g.get("startedByUid") !== uid && !triviaIsStaff(me) && !roomBoss) {
      throw new functionsV1.https.HttpsError("permission-denied", "Only the player who started it (or staff) can stop it.");
    }
    const now = Date.now();
    tx.update(triviaRef(roomId), { running: false, phase: "IDLE", question: "", options: [], updatedAtMs: now });
    triviaSay(tx, roomId, [`⏹ Trivia stopped by ${me.get("username") || "staff"}.`], now);
    return { ok: true };
  });
});

exports.triviaTop = functionsV1.https.onCall(async (data, context) => {
  requireAuth(context);
  const period = String((data && data.period) || "day") === "all" ? "all" : "day";
  const snap = period === "all"
    ? await db.collection("trivia_scores").orderBy("total", "desc").limit(10).get()
    : await db.collection("trivia_daily").doc(dhakaDateKey()).collection("users").orderBy("pts", "desc").limit(10).get();
  return {
    period,
    rows: snap.docs.map((d) => ({ username: String(d.get("username") || ""), pts: Number(d.get(period === "all" ? "total" : "pts") || 0) })),
  };
});

// =============================================================================
// ✨ ENTRY EFFECTS — a 30-day subscription bought with coins. When the owner
// enters a room, EVERYONE in it sees the effect (the app reads the public
// entry_fx_public/{usernameLower} doc when the "has entered" line arrives).
//   entry_fx/{uid}                 { owned: {id: expiresAtMs}, active, updatedAt }   (own read)
//   entry_fx_public/{usernameLower} { active, expiresAt, username }                   (everyone reads)
// Only these functions write them.
// =============================================================================
const ENTRY_FX_DAYS = 30;
const ENTRY_FX_SHOP = {
  sparkle: 100000, bubbles: 110000,        // 🌟 Classic
  sakura: 120000, snow: 120000,            // 🌸 Nature
  roses: 140000, hearts: 150000,           // 💖 Love
  confetti: 160000, disco: 200000,         // 🎉 Party
  fire: 180000, thunder: 220000,           // 🔥 Elements
  money: 250000, diamonds: 300000,         // 💰 Rich
  royal: 320000, carpet: 350000,           // 👑 Royal
  meteor: 380000, galaxy: 420000,          // 🚀 Legend
  aurora: 450000, phoenix: 500000,         // 🐉 Mythic
  butterfly: 130000, rainbow: 170000,      // 🌸 Nature
  neon: 240000,                            // 🎉 Party
  lanterns: 280000,                        // 🏮 Festival
  fireworks: 520000, lotus: 550000,        // 💎 Exclusive
  angel: 600000, frost: 600000,
  blackhole: 700000, dragon: 800000,
  // ✨ 20 new (2026-11)
  ocean: 130000, desert: 140000,           // 🌸 Nature
  tornado: 190000, ice: 210000, volcano: 230000, // 🔥 Elements
  glitch: 230000, hologram: 260000,        // 🎉 Party
  tiger: 260000, peacock: 290000, eagle: 340000, lion: 360000, // 🐾 Wild
  champagne: 270000, treasure: 330000,     // 💰 Rich
  palace: 380000,                          // 👑 Royal
  rocket: 360000, eclipse: 400000, spell: 410000, saturn: 430000, // 🚀 Legend
  unicorn: 460000,                         // 🐉 Mythic
  samurai: 650000,                         // 💎 Exclusive
};
function entryFxRef(uid) { return db.collection("entry_fx").doc(uid); }
function entryFxPublicRef(name) { return db.collection("entry_fx_public").doc(String(name || "").trim().toLowerCase()); }

// =============================================================================
// ⚽ SUPPORTER COLOURS (Discover › Supporter Colours): pick one of 25 football
// teams (top 5 leagues × 5) — your name shows in the team's colour with a small
// team badge in rooms, for 30 days, paid in coins. Buying again (same or another
// team) adds 30 days and switches to that team. A Style Studio / VIP colour,
// Lucky User pink and role colours still come first. Fan colours only — no club
// logos. users/{uid}.supporterTeam / supporterUntil are written ONLY here.
// =============================================================================
// Built-in price / days; miglife changes them on the Supporter Colours page (✏️),
// stored in app_settings/shop_overrides.supporter { price, days, prices }.
// price = the default for every team; prices.{team} = that team's own price
// (✏️ on the team), which wins over the default.
const SUPPORTER_PRICE = 50000;
const SUPPORTER_DAYS = 30;
const validSupporterPrice = (p) => Number.isInteger(p) && p >= 1000 && p <= 100000000;
function supporterTerms(ov, team) {
  const o = (ov && ov.supporter) || {};
  const own = team && o.prices && typeof o.prices === "object" ? o.prices[team] : undefined;
  return {
    price: validSupporterPrice(own) ? own : validSupporterPrice(o.price) ? o.price : SUPPORTER_PRICE,
    days: Number.isInteger(o.days) && o.days >= 1 && o.days <= 365 ? o.days : SUPPORTER_DAYS,
  };
}
const SUPPORTER_TEAMS = new Set([
  "manutd", "liverpool", "arsenal", "chelsea", "mancity",
  "realmadrid", "barcelona", "atletico", "sevilla", "valencia",
  "juventus", "milan", "inter", "napoli", "roma",
  "bayern", "dortmund", "leverkusen", "leipzig", "frankfurt",
  "psg", "marseille", "lyon", "monaco", "lille",
]);

exports.buySupporterColour = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const operationId = String((data && data.operationId) || "").trim();
  if (!/^[A-Za-z0-9_-]{8,128}$/.test(operationId)) throw new E("invalid-argument", "Missing operationId.");
  const team = String((data && data.team) || "");
  if (!SUPPORTER_TEAMS.has(team)) throw new E("invalid-argument", "Unknown team.");
  const { price, days } = supporterTerms(await readShopOverrides(), team);
  const userRef = db.collection("users").doc(uid);
  const opRef = db.collection("_operations").doc(operationId);
  const r = await db.runTransaction(async (tx) => {
    const [user, existingOp] = await Promise.all([tx.get(userRef), tx.get(opRef)]);
    if (existingOp.exists) return existingOp.data().result || {};
    if (!user.exists) throw new E("not-found", "User not found.");
    const username = String(user.get("username") || "");
    const balance = Number(user.get("balance") || 0);
    if (balance < price) {
      throw new E("failed-precondition", `You need ${price.toLocaleString("en-US")} coins for the Supporters Badge.`);
    }
    const now = Date.now();
    const current = Number(user.get("supporterUntil") || 0);
    const until = Math.max(now, current) + days * 24 * 60 * 60 * 1000;
    tx.update(userRef, {
      balance: balance - price,
      balanceUpdatedAt: FieldValue.serverTimestamp(),
      supporterTeam: team,
      supporterUntil: until,
      supporterPaused: FieldValue.delete(), // buying switches the badge ON
    });
    tx.set(userRef.collection("coin_transactions").doc(`supporter_${operationId}`), {
      type: "purchase", source: "shop", item: `supporter_${team}`, amount: -price,
      reason: `Supporters Badge (${days} days)`,
      balanceBefore: balance, balanceAfter: balance - price, operationId, createdAt: FieldValue.serverTimestamp(),
    });
    const result = { ok: true, team, until, balance: balance - price, username, renewed: current > now, price };
    tx.create(opRef, { type: "supporter_buy", uid, result, createdAt: FieldValue.serverTimestamp() });
    return result;
  });
  if (r && r.ok && r.username) {
    await alertUser(r.username,
      `⚽ Supporters Badge ${r.renewed ? "renewed" : "is on"} — ${formatCoins(r.price || price)} coins · until ${dhakaDate(r.until)}.`,
      "supporter_colour", { team: r.team }, `supporter_${operationId}`).catch(() => {});
  }
  return r ? { ok: r.ok, team: r.team, until: r.until, balance: r.balance } : r;
});

// ⚽ ON / OFF for the badge you bought (the days keep running). OFF parks the
// team in supporterPaused, so every room / profile / list that reads
// supporterTeam simply shows no badge; ON puts it back.
exports.toggleSupporterBadge = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const on = data && data.on === true;
  const userRef = db.collection("users").doc(uid);
  return db.runTransaction(async (tx) => {
    const u = await tx.get(userRef);
    if (!u.exists) throw new E("not-found", "User not found.");
    if (Number(u.get("supporterUntil") || 0) <= Date.now()) throw new E("failed-precondition", "Your Supporters Badge has ended.");
    const team = String(u.get("supporterTeam") || "");
    const paused = String(u.get("supporterPaused") || "");
    if (on) {
      if (!team && SUPPORTER_TEAMS.has(paused)) tx.update(userRef, { supporterTeam: paused, supporterPaused: FieldValue.delete() });
    } else if (team) {
      tx.update(userRef, { supporterPaused: team, supporterTeam: FieldValue.delete() });
    }
    return { ok: true, on };
  });
});

// ✏️ miglife sets the Supporter Colours price (and days) for every team, or —
// with { team } — one team's own price ({ team, reset: true } = back to the
// default price).
// 🎁 Gift Shops (web /gifts): add / edit / delete a gift and upload its picture.
// Storage and Firestore rules only know founders/{uid}, but a Staff / Admin
// id can get "gift_shop" from its role or its own ticked tools — so those
// people saw the Edit button and then got storage/unauthorized. The server
// checks the same tools the page shows (founderPermsOf) and does the write.
const GIFT_SHOP_ID_RE = /^[A-Za-z0-9_-]{1,80}$/;
exports.giftShopManage = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  if (!(await hasFounderPerm(uid, "gift_shop"))) throw new E("permission-denied", "You don't have the Gift Shops tool.");
  const action = String(data?.action || "");
  const id = String(data?.id || "");
  if (!GIFT_SHOP_ID_RE.test(id)) throw new E("invalid-argument", "Unknown gift.");
  const ref = db.collection("gift_catalog").doc(id);
  if (action === "upload") {
    const contentType = String(data?.contentType || "").toLowerCase();
    if (!/^image\/(png|jpeg|jpg|gif|webp)$/.test(contentType)) throw new E("invalid-argument", "Please choose a picture (PNG or JPG).");
    const buf = Buffer.from(String(data?.fileBase64 || ""), "base64");
    if (buf.length < 50) throw new E("invalid-argument", "The picture is empty.");
    if (buf.length > 5 * 1024 * 1024) throw new E("invalid-argument", "That picture is too big (over 5 MB). Please choose a smaller one.");
    const path = `gift_images/${id}.jpg`;
    const token = crypto.randomUUID();
    const bucket = require("firebase-admin/storage").getStorage().bucket();
    await bucket.file(path).save(buf, {
      resumable: false,
      metadata: { contentType, cacheControl: "public, max-age=31536000", metadata: { firebaseStorageDownloadTokens: token } },
    });
    const url = `https://firebasestorage.googleapis.com/v0/b/${bucket.name}/o/${encodeURIComponent(path)}?alt=media&token=${token}&v=${Date.now()}`;
    return { ok: true, url };
  }
  if (action === "save") {
    const g = data?.gift || {};
    const str = (v, n) => String(v ?? "").trim().slice(0, n);
    const name = str(g.name, 60);
    const price = Math.floor(Number(g.price_coins));
    if (!name) throw new E("invalid-argument", "Write the gift's name.");
    if (!Number.isFinite(price) || price < 5 || price > 1000000000) throw new E("invalid-argument", "Price: at least 5 coins.");
    const imageUrl = str(g.imageUrl, 1000);
    if (imageUrl && !/^https:\/\//i.test(imageUrl)) throw new E("invalid-argument", "The picture must be a web link.");
    const out = {
      name,
      category: str(g.category, 40) || "Special",
      price_coins: price,
      icon: str(g.icon, 16) || "🎁",
      imageUrl,
      animation: str(g.animation, 200),
      limited: g.limited === true,
      featured: g.featured === true,
      active: g.active !== false,
      sortOrder: Math.floor(Number(g.sortOrder) || 0),
    };
    if (data?.isNew === true) {
      if ((await ref.get()).exists) throw new E("already-exists", "That gift already exists.");
      await ref.set({ ...out, createdAt: FieldValue.serverTimestamp(), createdBy: uid });
    } else {
      if (!(await ref.get()).exists) throw new E("not-found", "Gift not found.");
      await ref.set({ ...out, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid }, { merge: true });
    }
    return { ok: true };
  }
  if (action === "delete") {
    await ref.delete();
    return { ok: true };
  }
  throw new E("invalid-argument", "Unknown action.");
});

exports.founderSetSupporterPrice = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can set the price.");
  if (data && data.team !== undefined && data.team !== null && data.team !== "") {
    const team = String(data.team);
    if (!SUPPORTER_TEAMS.has(team)) throw new E("invalid-argument", "Unknown team.");
    // 📷 the team's picture miglife uploaded (supporter_badges/{team}.*);
    // "" = back to the jersey. Shown instead of the jersey everywhere.
    if (data.image !== undefined) {
      const image = String(data.image || "").trim();
      if (image && !(image.startsWith("https://firebasestorage.googleapis.com/") && image.includes(`/o/supporter_badges%2F${team}.`))) {
        throw new E("invalid-argument", "Upload the picture first.");
      }
      await SHOP_OVERRIDES_REF().set(
        { supporter: { images: { [team]: image || FieldValue.delete() } }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid },
        { merge: true });
      return { ok: true, team, image };
    }
    if (data.reset === true) {
      await SHOP_OVERRIDES_REF().set(
        { supporter: { prices: { [team]: FieldValue.delete() } }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid },
        { merge: true });
      return { ok: true, team, reset: true };
    }
    const teamPrice = Number(data.price);
    if (!validSupporterPrice(teamPrice)) throw new E("invalid-argument", "Price: a whole number from 1,000 to 100,000,000.");
    await SHOP_OVERRIDES_REF().set(
      { supporter: { prices: { [team]: teamPrice } }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid },
      { merge: true });
    return { ok: true, team, price: teamPrice };
  }
  const price = Number(data && data.price);
  const days = Number(data && data.days);
  if (!Number.isInteger(price) || price < 1000 || price > 100000000) throw new E("invalid-argument", "Price: a whole number from 1,000 to 100,000,000.");
  if (!Number.isInteger(days) || days < 1 || days > 365) throw new E("invalid-argument", "Days: 1 to 365.");
  await SHOP_OVERRIDES_REF().set({ supporter: { price, days }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid }, { merge: true });
  return { ok: true, price, days };
});

// 👑 miglife gives ANY room to another owner (Room Info → Edit → Owner ✎).
// The new owner gets the room's owner powers; the old owner loses them. A room
// with no rooms/{name} doc yet (an official room) gets one holding the owner.
exports.founderTransferRoomOwner = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can change a room's owner.");
  const roomName = String((data && data.roomName) || "").trim();
  const target = String((data && data.newOwner) || "").trim().replace(/^@/, "");
  if (!roomName || roomName.length > 100 || roomName.includes("/")) throw new E("invalid-argument", "Room name is missing.");
  if (!target) throw new E("invalid-argument", "Write the new owner's MIG ID.");
  let q = await db.collection("users").where("usernameLower", "==", target.toLowerCase()).limit(1).get();
  if (q.empty) q = await db.collection("users").where("username", "==", target).limit(1).get();
  if (q.empty) throw new E("not-found", `User not found: ${target}`);
  const owner = q.docs[0];
  const ownerName = String(owner.get("username") || target).trim();
  const roomRef = db.collection("rooms").doc(roomName);
  const oldOwner = await db.runTransaction(async (tx) => {
    const snap = await tx.get(roomRef);
    const d = snap.exists ? snap.data() || {} : {};
    const update = {
      ownerUid: owner.id,
      ownerName,
      // 🔓 owner miglife → a Public room; owner anyone else → a Private room
      // (the same rule as making a room: miglife's rooms are Public, others' Private)
      privacy: isMainFounderName(ownerName) ? "Public" : "Private",
      ownerChangedAt: FieldValue.serverTimestamp(),
      ownerChangedBy: uid,
    };
    // Keep the new owner in the member list the rules use for user rooms.
    if (Array.isArray(d.members)) update.members = FieldValue.arrayUnion(owner.id);
    tx.set(roomRef, update, { merge: true });
    return String(d.ownerName || "");
  });
  await db.collection("room_messages").doc(roomName).collection("messages").add({
    text: `👑 ${ownerName} is now the owner of ${roomName}.`,
    sender: "miGlife",
    senderUid: null,
    type: "moderation",
    giftName: "",
    createdAt: FieldValue.serverTimestamp(),
    clientCreatedAt: Date.now(),
  }).catch((err) => console.error("founderTransferRoomOwner: room line failed", err));
  console.log("founderTransferRoomOwner", { roomName, from: oldOwner, to: ownerName });
  return { ok: true, roomName, ownerName, oldOwner };
});

exports.buyEntryEffect = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const operationId = String((data && data.operationId) || "").trim();
  if (!/^[A-Za-z0-9_-]{8,128}$/.test(operationId)) throw new E("invalid-argument", "Missing operationId.");
  const id = String((data && data.id) || "");
  if (!Object.prototype.hasOwnProperty.call(ENTRY_FX_SHOP, id)) throw new E("invalid-argument", "Unknown effect.");
  const fxOv = ((await readShopOverrides()).entryFx || {})[id] || {};
  if (fxOv.hidden === true) throw new E("failed-precondition", "This effect is no longer sold.");
  const price = Number.isInteger(fxOv.price) && fxOv.price > 0 ? fxOv.price : ENTRY_FX_SHOP[id];
  const userRef = db.collection("users").doc(uid);
  const fxRef = entryFxRef(uid);
  const opRef = db.collection("_operations").doc(operationId);
  return db.runTransaction(async (tx) => {
    const [user, fx, existingOp] = await Promise.all([tx.get(userRef), tx.get(fxRef), tx.get(opRef)]);
    if (existingOp.exists) return existingOp.data().result || {};
    if (!user.exists) throw new E("not-found", "User not found.");
    const username = String(user.get("username") || "");
    if (!username) throw new E("failed-precondition", "No username.");
    const balance = Number(user.get("balance") || 0);
    if (balance < price) throw new E("failed-precondition", `You need ${price.toLocaleString("en-US")} coins for this effect.`);
    const now = Date.now();
    const owned = (fx.exists && fx.get("owned") && typeof fx.get("owned") === "object") ? fx.get("owned") : {};
    // buying again while it is still running ADDS 30 days
    const from = Math.max(now, Number(owned[id] || 0));
    const expiresAt = from + ENTRY_FX_DAYS * 24 * 60 * 60 * 1000;
    tx.update(userRef, { balance: balance - price, balanceUpdatedAt: FieldValue.serverTimestamp() });
    tx.set(userRef.collection("coin_transactions").doc(`entryfx_${operationId}`), {
      type: "purchase", source: "shop", item: `entry_effect_${id}`, amount: -price,
      balanceBefore: balance, balanceAfter: balance - price, operationId, createdAt: FieldValue.serverTimestamp(),
    });
    // A NEW effect switches on right away. "+30 days" on an effect you already
    // own only adds time — it no longer switches off the one you have on.
    const extending = Number(owned[id] || 0) > now;
    const currentActive = String((fx.exists && fx.get("active")) || "none");
    const currentActiveLive = currentActive !== "none" && Number(owned[currentActive] || 0) > now;
    const newActive = extending && currentActiveLive ? currentActive : id;
    tx.set(fxRef, { owned: { [id]: expiresAt }, active: newActive, username, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    const publicExpires = newActive === id ? expiresAt : Number(owned[newActive] || 0);
    tx.set(entryFxPublicRef(username), { active: newActive, expiresAt: publicExpires, username, updatedAt: FieldValue.serverTimestamp() });
    const result = { ok: true, id, active: newActive, expiresAt, balance: balance - price, username, price, extending };
    tx.create(opRef, { type: "entry_fx_buy", uid, result, createdAt: FieldValue.serverTimestamp() });
    return result;
  }).then(async (r) => {
    // 🔔 confirm the purchase in migAlerts
    if (r && r.ok && r.username) {
      const fxName = String(fxOv.name || "").trim() || id.charAt(0).toUpperCase() + id.slice(1);
      await alertUser(r.username,
        `✨ Entry Effect "${fxName}" ${r.extending ? "renewed" : "is active"} — ${formatCoins(r.price)} coins · until ${dhakaDate(r.expiresAt)}.`,
        "entry_effect", { effectId: id }, `entryfx_${operationId}`);
    }
    return r ? { ok: r.ok, id: r.id, active: r.active, expiresAt: r.expiresAt, balance: r.balance } : r;
  });
});

// Pick which owned (not expired) effect plays on entry, or "none" to switch it off.
exports.setEntryEffect = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const id = String((data && data.id) || "none");
  const fxRef = entryFxRef(uid);
  return db.runTransaction(async (tx) => {
    const [fx, user] = await Promise.all([tx.get(fxRef), tx.get(db.collection("users").doc(uid))]);
    const username = String((user.exists && user.get("username")) || "");
    if (!username) throw new E("failed-precondition", "No username.");
    const owned = (fx.exists && fx.get("owned") && typeof fx.get("owned") === "object") ? fx.get("owned") : {};
    if (id === "none") {
      tx.set(fxRef, { active: "none", updatedAt: FieldValue.serverTimestamp() }, { merge: true });
      tx.set(entryFxPublicRef(username), { active: "none", expiresAt: 0, username, updatedAt: FieldValue.serverTimestamp() });
      return { ok: true, id: "none" };
    }
    if (!Object.prototype.hasOwnProperty.call(ENTRY_FX_SHOP, id)) throw new E("invalid-argument", "Unknown effect.");
    const expiresAt = Number(owned[id] || 0);
    if (expiresAt <= Date.now()) throw new E("permission-denied", "Buy this effect first (or it has expired).");
    tx.set(fxRef, { active: id, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    tx.set(entryFxPublicRef(username), { active: id, expiresAt, username, updatedAt: FieldValue.serverTimestamp() });
    return { ok: true, id, expiresAt };
  });
});

// =============================================================================
// 🎵 PROFILE THEME SONGS — a 15-second tune plays when someone opens your
// profile. 30 days, paid in coins. The tunes are notes the apps play
// themselves (lib/profileSongs.ts / ProfileSongs.kt) — no music files.
// Stored next to the Entry Effects (same rules: only these functions write):
//   entry_fx/{uid}                         { songs: {id: expiresAtMs}, songActive }   (own read)
//   entry_fx_public/song_{usernameLower}   { active, expiresAt, username }           (everyone reads)
// =============================================================================
const PROFILE_SONG_DAYS = 30;
const PROFILE_SONG_SHOP = { royal: 150000, bells: 100000, lofi: 120000, love: 140000, victory: 130000, ektara: 160000,
  sad01: 120000, sad02: 120000, sad03: 120000, sad04: 120000, sad05: 120000, sad06: 120000, sad07: 120000, sad08: 120000, sad09: 120000, sad10: 120000, sad11: 120000, sad12: 120000, sad13: 120000, sad14: 120000, sad15: 120000, sad16: 120000, sad17: 120000, sad18: 120000, sad19: 120000, sad20: 120000 ,
  flute01: 150000, flute02: 150000, flute03: 150000, flute04: 150000, flute05: 150000, flute06: 150000, flute07: 150000, flute08: 150000, flute09: 150000, flute10: 150000, flute11: 150000, flute12: 150000, flute13: 150000, flute14: 150000, flute15: 150000, flute16: 150000, flute17: 150000, flute18: 150000, flute19: 150000, flute20: 150000 };
const PROFILE_SONG_NAMES = { royal: "Royal Fanfare", bells: "Happy Bells", lofi: "Lo-fi Night", love: "Love Piano", victory: "Victory", ektara: "Ektara Folk",
  sad01: "Rainy Window", sad02: "Broken Heart", sad03: "Lonely Night", sad04: "Tears", sad05: "Missing You", sad06: "Last Goodbye", sad07: "Empty Room", sad08: "Autumn Leaves", sad09: "Silent Moon", sad10: "Faded Memory", sad11: "Cold Rain", sad12: "Lost Love", sad13: "Distant Star", sad14: "Grey Sky", sad15: "Ocean of Tears", sad16: "Alone Again", sad17: "Midnight Blue", sad18: "Paper Boat", sad19: "Old Letter", sad20: "Sad Flute" ,
  flute01: "Bansuri Lament", flute02: "Village Dusk", flute03: "River Goodbye", flute04: "Ma's Lullaby", flute05: "Monsoon Night", flute06: "Lonely Boatman", flute07: "Empty Courtyard", flute08: "Memories of Home", flute09: "Biraha", flute10: "Evening Lamp", flute11: "Fading Footsteps", flute12: "Wounded Heart", flute13: "Moonlit Riverbank", flute14: "Unsent Words", flute15: "Last Train", flute16: "Withered Flower", flute17: "Silent Tears", flute18: "Far From Home", flute19: "Endless Wait", flute20: "Lost Melody" };
function profileSongPublicRef(name) { return db.collection("entry_fx_public").doc(`song_${String(name || "").trim().toLowerCase()}`); }

exports.buyProfileSong = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const operationId = String((data && data.operationId) || "").trim();
  if (!/^[A-Za-z0-9_-]{8,128}$/.test(operationId)) throw new E("invalid-argument", "Missing operationId.");
  const id = String((data && data.id) || "");
  const overrides = await readShopOverrides();
  // 🎤 one of miglife's own uploaded songs (shown in the shop = on)
  const custom = (overrides.songCatalog || {})[id];
  const isBuiltIn = Object.prototype.hasOwnProperty.call(PROFILE_SONG_SHOP, id);
  if (!isBuiltIn && !(custom && custom.on !== false && Number.isInteger(custom.price))) throw new E("invalid-argument", "Unknown song.");
  const ov = isBuiltIn ? ((overrides.profileSong || {})[id] || {}) : { name: custom.name, price: custom.price };
  const price = Number.isInteger(ov.price) && ov.price > 0 ? ov.price : PROFILE_SONG_SHOP[id];
  const userRef = db.collection("users").doc(uid);
  const fxRef = entryFxRef(uid);
  const opRef = db.collection("_operations").doc(operationId);
  return db.runTransaction(async (tx) => {
    const [user, fx, existingOp] = await Promise.all([tx.get(userRef), tx.get(fxRef), tx.get(opRef)]);
    if (existingOp.exists) return existingOp.data().result || {};
    if (!user.exists) throw new E("not-found", "User not found.");
    const username = String(user.get("username") || "");
    if (!username) throw new E("failed-precondition", "No username.");
    const balance = Number(user.get("balance") || 0);
    if (balance < price) throw new E("failed-precondition", `You need ${price.toLocaleString("en-US")} coins for this song.`);
    const now = Date.now();
    const owned = (fx.exists && fx.get("songs") && typeof fx.get("songs") === "object") ? fx.get("songs") : {};
    // buying again while it is still running ADDS 30 days
    const from = Math.max(now, Number(owned[id] || 0));
    const expiresAt = from + PROFILE_SONG_DAYS * 24 * 60 * 60 * 1000;
    tx.update(userRef, { balance: balance - price, balanceUpdatedAt: FieldValue.serverTimestamp() });
    tx.set(userRef.collection("coin_transactions").doc(`song_${operationId}`), {
      type: "purchase", source: "shop", item: `profile_song_${id}`, amount: -price,
      balanceBefore: balance, balanceAfter: balance - price, operationId, createdAt: FieldValue.serverTimestamp(),
    });
    // a NEW song switches on at once; +30 days on one you own only adds time
    const extending = Number(owned[id] || 0) > now;
    const current = String((fx.exists && fx.get("songActive")) || "none");
    const currentLive = current !== "none" && Number(owned[current] || 0) > now;
    const newActive = extending && currentLive ? current : id;
    tx.set(fxRef, { songs: { [id]: expiresAt }, songActive: newActive, username, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    const publicExpires = newActive === id ? expiresAt : Number(owned[newActive] || 0);
    tx.set(profileSongPublicRef(username), { active: newActive, expiresAt: publicExpires, username, updatedAt: FieldValue.serverTimestamp() });
    const result = { ok: true, id, active: newActive, expiresAt, balance: balance - price, username, price, extending };
    tx.create(opRef, { type: "profile_song_buy", uid, result, createdAt: FieldValue.serverTimestamp() });
    return result;
  }).then(async (r) => {
    if (r && r.ok && r.username) {
      const songName = String(ov.name || "").trim() || PROFILE_SONG_NAMES[id] || id;
      await alertUser(r.username,
        `🎵 Profile Song "${songName}" ${r.extending ? "renewed" : "is on"} — ${formatCoins(r.price)} coins · until ${dhakaDate(r.expiresAt)}.`,
        "profile_song", { songId: id }, `song_${operationId}`);
    }
    return r ? { ok: r.ok, id: r.id, active: r.active, expiresAt: r.expiresAt, balance: r.balance } : r;
  });
});

// Pick which owned (not expired) song plays on your profile, or "none".
exports.setProfileSong = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const id = String((data && data.id) || "none");
  const fxRef = entryFxRef(uid);
  return db.runTransaction(async (tx) => {
    const [fx, user] = await Promise.all([tx.get(fxRef), tx.get(db.collection("users").doc(uid))]);
    const username = String((user.exists && user.get("username")) || "");
    if (!username) throw new E("failed-precondition", "No username.");
    const owned = (fx.exists && fx.get("songs") && typeof fx.get("songs") === "object") ? fx.get("songs") : {};
    if (id === "none") {
      tx.set(fxRef, { songActive: "none", updatedAt: FieldValue.serverTimestamp() }, { merge: true });
      tx.set(profileSongPublicRef(username), { active: "none", expiresAt: 0, username, updatedAt: FieldValue.serverTimestamp() });
      return { ok: true, id: "none" };
    }
    if (!Object.prototype.hasOwnProperty.call(PROFILE_SONG_SHOP, id) && !/^up_[a-f0-9]{12}$/.test(id)) throw new E("invalid-argument", "Unknown song.");
    const expiresAt = Number(owned[id] || 0);
    if (expiresAt <= Date.now()) throw new E("permission-denied", "Buy this song first (or it has expired).");
    tx.set(fxRef, { songActive: id, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    tx.set(profileSongPublicRef(username), { active: id, expiresAt, username, updatedAt: FieldValue.serverTimestamp() });
    return { ok: true, id, expiresAt };
  });
});

// 🎤 miglife's OWN songs (any music, up to 5 minutes): uploaded from miGlife
// secret › Profile Songs. The file goes to Storage (profile_songs/{id}.mp3,
// read through its download link) and the song into
// app_settings/shop_overrides.songCatalog.{id} = { name, emoji, mood, price,
// url, seconds, on, createdAt } — the shop shows it in the 🎤 miGlife tab and
// it is bought / switched on like any other Profile Song.
//   { action: "add", name, emoji, mood, price, seconds, contentType, fileBase64 }
//   { action: "update", id, name?, emoji?, mood?, price?, on? }   (on: false = hidden from the shop)
const PROFILE_SONG_MAX_SECONDS = 300;
const PROFILE_SONG_MAX_BYTES = 7 * 1024 * 1024;
exports.founderProfileSong = functionsV1.runWith({ timeoutSeconds: 120, memory: "512MB" }).https.onCall(async (data, context) => {
  await assertSecretOpen(context && context.auth);   // 🔒 miGlife secret must be open
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can add songs.");
  const action = String(data?.action || "");
  const clean = (v, max) => String(v || "").replace(/[\u0000-\u001f]/g, "").trim().slice(0, max);
  const priceOk = (p) => Number.isInteger(p) && p >= 1000 && p <= 100000000;
  const ref = SHOP_OVERRIDES_REF();
  if (action === "add") {
    const name = clean(data?.name, 30);
    if (!name) throw new E("invalid-argument", "Give the song a name.");
    const price = Math.floor(Number(data?.price));
    if (!priceOk(price)) throw new E("invalid-argument", "Price must be 1,000 – 100,000,000 coins.");
    const seconds = Math.round(Number(data?.seconds) || 0);
    if (!(seconds >= 1 && seconds <= PROFILE_SONG_MAX_SECONDS)) throw new E("invalid-argument", "The song must be 1 second to 5 minutes long.");
    const contentType = String(data?.contentType || "").toLowerCase();
    if (!/^audio\/(mpeg|mp3|mp4|aac|x-m4a|m4a|ogg|wav|x-wav|webm)$/.test(contentType)) throw new E("invalid-argument", "Upload an MP3, M4A, AAC, OGG or WAV file.");
    const buf = Buffer.from(String(data?.fileBase64 || ""), "base64");
    if (buf.length < 1000) throw new E("invalid-argument", "The file is empty.");
    if (buf.length > PROFILE_SONG_MAX_BYTES) throw new E("invalid-argument", "The file is bigger than 7 MB — save it as a 128 kbps MP3 and try again.");
    const ext = contentType.includes("mpeg") || contentType.includes("mp3") ? "mp3"
      : contentType.includes("ogg") ? "ogg" : contentType.includes("wav") ? "wav" : contentType.includes("webm") ? "webm" : "m4a";
    const id = "up_" + crypto.randomBytes(6).toString("hex");
    const path = `profile_songs/${id}.${ext}`;
    const token = crypto.randomUUID();
    const bucket = require("firebase-admin/storage").getStorage().bucket();
    await bucket.file(path).save(buf, {
      resumable: false,
      metadata: { contentType, cacheControl: "public, max-age=31536000", metadata: { firebaseStorageDownloadTokens: token } },
    });
    const url = `https://firebasestorage.googleapis.com/v0/b/${bucket.name}/o/${encodeURIComponent(path)}?alt=media&token=${token}`;
    const song = {
      name, emoji: clean(data?.emoji, 8) || "🎵", mood: clean(data?.mood, 40), price, seconds,
      url, path, on: true, createdAt: Date.now(),
    };
    await ref.set({ songCatalog: { [id]: song } }, { merge: true });
    return { ok: true, id, url };
  }
  if (action === "update") {
    const id = String(data?.id || "");
    if (!/^up_[a-f0-9]{12}$/.test(id)) throw new E("invalid-argument", "Unknown song.");
    const snap = await ref.get();
    const cur = ((snap.exists && snap.get("songCatalog")) || {})[id];
    if (!cur) throw new E("not-found", "Song not found.");
    const upd = {};
    if (data?.name !== undefined) { const n = clean(data.name, 30); if (!n) throw new E("invalid-argument", "Give the song a name."); upd.name = n; }
    if (data?.emoji !== undefined) upd.emoji = clean(data.emoji, 8) || "🎵";
    if (data?.mood !== undefined) upd.mood = clean(data.mood, 40);
    if (data?.price !== undefined) { const p = Math.floor(Number(data.price)); if (!priceOk(p)) throw new E("invalid-argument", "Price must be 1,000 – 100,000,000 coins."); upd.price = p; }
    if (data?.on !== undefined) upd.on = data.on === true;
    await ref.set({ songCatalog: { [id]: upd } }, { merge: true });
    return { ok: true, id };
  }
  throw new E("invalid-argument", "Unknown action.");
});

// =====================================================================
// 📺 LIVE SPORTS — live scores + today's schedule (cricket + football)
// ---------------------------------------------------------------------
// Keys live ONLY in functions/.env (never in the app / GitHub):
//   CRICAPI_KEY=xxxxxxxx         (cricketdata.org — free 100 calls/day)
//   FOOTBALL_DATA_KEY=xxxxxxxx   (football-data.org — free tier)
// Writes one doc: live_sports/today  → the app only reads it.
// =====================================================================
function sportsGetJson(url, headers = {}) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers, timeout: 15000 }, (res) => {
      let body = "";
      res.setEncoding("utf8");
      res.on("data", (c) => { body += c; });
      res.on("end", () => {
        if (res.statusCode < 200 || res.statusCode >= 300) {
          return reject(new Error(`HTTP ${res.statusCode}: ${body.slice(0, 200)}`));
        }
        try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
      });
    });
    req.on("timeout", () => req.destroy(new Error("timeout")));
    req.on("error", reject);
  });
}

// Bangladesh date (UTC+6) as "YYYY-MM-DD".
function dhakaDay(ms) {
  return new Date(ms + 6 * 3600 * 1000).toISOString().slice(0, 10);
}

function cricketRow(m) {
  const info = Array.isArray(m.teamInfo) ? m.teamInfo : [];
  const teams = Array.isArray(m.teams) ? m.teams : [];
  const home = teams[0] || (info[0] && info[0].name) || "";
  const away = teams[1] || (info[1] && info[1].name) || "";
  const teamOf = (name) => info.find((x) => x && x.name === name) || {};
  const scores = Array.isArray(m.score) ? m.score : [];
  const scoreFor = (name) => scores
    .filter((s) => s && typeof s.inning === "string" && s.inning.toLowerCase().startsWith(String(name).toLowerCase()))
    .map((s) => `${s.r}/${s.w} (${s.o})`)
    .join(" & ");
  let startMs = 0;
  if (m.dateTimeGMT) {
    const raw = String(m.dateTimeGMT);
    const t = Date.parse(raw.endsWith("Z") ? raw : `${raw}Z`);
    if (!Number.isNaN(t)) startMs = t;
  }
  const status = m.matchEnded ? "FINISHED" : (m.matchStarted ? "LIVE" : "UPCOMING");
  return {
    sport: "cricket",
    id: String(m.id || ""),
    league: String(m.name || "").split(",").slice(1).join(",").trim() || String(m.matchType || "").toUpperCase(),
    leagueLogo: "",
    format: String(m.matchType || "").toUpperCase(),
    home, away,
    homeShort: teamOf(home).shortname || "", awayShort: teamOf(away).shortname || "",
    homeLogo: teamOf(home).img || "", awayLogo: teamOf(away).img || "",
    homeScore: scoreFor(home), awayScore: scoreFor(away),
    status,
    statusText: String(m.status || ""),
    startMs,
    venue: String(m.venue || ""),
  };
}

function footballRow(m) {
  const st = String(m.status || "");
  const status = (st === "IN_PLAY" || st === "PAUSED" || st === "LIVE") ? "LIVE"
    : (st === "FINISHED" || st === "AWARDED") ? "FINISHED"
    : (st === "POSTPONED" || st === "CANCELLED" || st === "SUSPENDED") ? "OFF"
    : "UPCOMING";
  const ft = (m.score && m.score.fullTime) || {};
  const hasScore = ft.home !== null && ft.home !== undefined;
  const statusText = st === "PAUSED" ? "Half time"
    : st === "IN_PLAY" ? (m.minute ? `${m.minute}'` : "Live")
    : st === "FINISHED" ? "Full time"
    : status === "OFF" ? st.charAt(0) + st.slice(1).toLowerCase()
    : "";
  const home = m.homeTeam || {};
  const away = m.awayTeam || {};
  return {
    sport: "football",
    id: String(m.id || ""),
    league: (m.competition && m.competition.name) || "",
    leagueLogo: (m.competition && m.competition.emblem) || "",
    format: "",
    home: home.shortName || home.name || "TBD",
    away: away.shortName || away.name || "TBD",
    homeShort: home.tla || "", awayShort: away.tla || "",
    homeLogo: home.crest || "", awayLogo: away.crest || "",
    homeScore: hasScore ? String(ft.home) : "",
    awayScore: hasScore ? String(ft.away) : "",
    status,
    statusText,
    startMs: Date.parse(m.utcDate || "") || 0,
    venue: String(m.venue || ""),
  };
}

const SPORTS_ORDER = { LIVE: 0, UPCOMING: 1, FINISHED: 2, OFF: 3 };
function sortSportsRows(rows) {
  return rows.sort((a, b) => ((SPORTS_ORDER[a.status] || 0) - (SPORTS_ORDER[b.status] || 0)) || (a.startMs - b.startMs));
}

// cricScore (CricAPI): ONE call lists every live, upcoming and just-finished
// match ("Bangladesh [BAN]", ms: fixture | live | result). The old
// matches/currentMatches pair only gave the first 25 of a long list (often old
// games), so today's matches (e.g. BAN vs AFG) could be missing.
function cricTeam(raw) {
  const s = String(raw || "").trim();
  const m = /^(.*?)\s*\[([^\]]+)\]\s*$/.exec(s);
  return m ? { name: m[1].trim(), short: m[2].trim() } : { name: s, short: "" };
}
function cricScoreRow(m) {
  const t1 = cricTeam(m.t1), t2 = cricTeam(m.t2);
  const ms = String(m.ms || "").toLowerCase();
  const status = ms === "live" ? "LIVE" : ms === "result" ? "FINISHED" : "UPCOMING";
  let startMs = 0;
  if (m.dateTimeGMT) {
    const raw = String(m.dateTimeGMT);
    const t = Date.parse(raw.endsWith("Z") ? raw : `${raw}Z`);
    if (!Number.isNaN(t)) startMs = t;
  }
  return {
    sport: "cricket",
    id: String(m.id || ""),
    league: String(m.series || "").trim() || String(m.matchType || "").toUpperCase(),
    leagueLogo: "",
    format: String(m.matchType || "").toUpperCase(),
    home: t1.name, away: t2.name,
    homeShort: t1.short, awayShort: t2.short,
    homeLogo: String(m.t1img || ""), awayLogo: String(m.t2img || ""),
    homeScore: String(m.t1s || ""), awayScore: String(m.t2s || ""),
    status,
    statusText: String(m.status || ""),
    startMs,
    venue: "",
  };
}

// CricAPI answers HTTP 200 even when it fails (wrong key, daily limit used up):
// { status: "failure", reason: "..." }. That used to look like "no matches today".
function cricApiData(j) {
  if (!j || j.status !== "success") {
    throw new Error(`CricAPI: ${(j && (j.reason || j.status)) || "no answer"}`);
  }
  return Array.isArray(j.data) ? j.data : [];
}

// One refresh of live_sports/today. force = miglife's "Refresh now" (skips the
// "every 20 minutes" cricket spacing). Any problem is written to the doc
// (problems.cricket / problems.football) so the Live Scores page can show why
// nothing is listed.
async function runLiveSportsRefresh(force) {
  // Keys pasted with spaces or quotes around them still work.
  const cleanKey = (v) => String(v || "").trim().replace(/^["']+|["']+$/g, "").trim();
  const cricKey = cleanKey(process.env.CRICAPI_KEY);
  const footKey = cleanKey(process.env.FOOTBALL_DATA_KEY);
  const now = Date.now();
  const today = dhakaDay(now);
  const ref = db.collection("live_sports").doc("today");
  const metaRef = db.collection("live_sports_meta").doc("state");
  const [prevSnap, metaSnap] = await Promise.all([ref.get(), metaRef.get()]);
  const prev = prevSnap.exists ? prevSnap.data() : {};
  const meta = metaSnap.exists ? metaSnap.data() : {};
  const prevProblems = (prev && prev.problems) || {};
  const out = { updatedAtMs: now, day: today, keys: { cricket: !!cricKey, football: !!footKey }, problems: {} };
  const metaOut = {};

  // ---- Cricket: cricScore, at most every 20 min (CricAPI free = 100 calls/day → ~72) ----
  if (!cricKey) {
    out.problems.cricket = "CRICAPI_KEY is not set in functions/.env";
  } else if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(cricKey)) {
    // A CricAPI key looks like 1a2b3c4d-1a2b-1a2b-1a2b-1a2b3c4d5e6f (32 letters/digits, 4 dashes).
    out.problems.cricket = `CRICAPI_KEY is not a CricAPI key (it has ${cricKey.length} characters; a key looks like xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx). Copy it again from cricketdata.org → API Keys.`;
    if (Array.isArray(prev.cricket)) out.cricket = prev.cricket;
  } else {
    // every 24 min (+ currentMatches every 2nd run) keeps us under CricAPI's 100 calls/day
    const due = force || now - (meta.cricScoreAtMs || 0) >= 24 * 60 * 1000 || meta.cricDay !== today;
    if (due) {
      try {
        const data = cricApiData(await sportsGetJson(`https://api.cricapi.com/v1/cricScore?apikey=${encodeURIComponent(cricKey)}`));
        // A Test / first-class match runs 4-5 days: on day 2+ its start date is NOT
        // today, and at stumps / lunch / tea / rain CricAPI may not call it "live".
        // Such a match (started in the last 5 days, no result yet) is still going
        // on → keep it and show it as LIVE.
        const MULTI_DAY_MS = 5 * 24 * 3600 * 1000;
        const rows = data.map(cricScoreRow)
          .map((r) => (r.status === "UPCOMING" && r.startMs > 0 && r.startMs <= now && now - r.startMs < MULTI_DAY_MS)
            ? { ...r, status: "LIVE" } : r)
          .filter((r) => r.id && (r.status === "LIVE" || dhakaDay(r.startMs || 0) === today));

        // cricScore sometimes leaves out a match that IS being played (seen with the
        // AFG v BAN Test). currentMatches lists matches in progress, so every 2nd
        // run (or on "Refresh now") it fills in any running match cricScore missed.
        // Between those runs the extra matches found last time are kept.
        let extra = [];
        const extraDue = force || now - (meta.cricCurrentAtMs || 0) >= 45 * 60 * 1000 || meta.cricDay !== today;
        if (extraDue) {
          try {
            const cur = cricApiData(await sportsGetJson(`https://api.cricapi.com/v1/currentMatches?apikey=${encodeURIComponent(cricKey)}&offset=0`));
            extra = cur
              .filter((m) => m && m.matchStarted && !m.matchEnded)
              .map(cricketRow)
              .filter((r) => r.id && (!r.startMs || now - r.startMs < MULTI_DAY_MS))
              .map((r) => ({ ...r, status: "LIVE" }));
            metaOut.cricCurrentAtMs = now;
            metaOut.cricExtra = extra;
          } catch (e) {
            console.warn("refreshLiveSports currentMatches:", e.message);
            extra = Array.isArray(meta.cricExtra) ? meta.cricExtra : [];
          }
        } else {
          extra = Array.isArray(meta.cricExtra) ? meta.cricExtra : [];
        }
        // same match in both lists? keep the cricScore one (same CricAPI match id,
        // or the same two teams).
        const teamKey = (r) => [String(r.home || "").toLowerCase(), String(r.away || "").toLowerCase()].sort().join("|");
        const haveIds = new Set(rows.map((r) => r.id));
        const haveTeams = new Set(rows.map(teamKey));
        for (const r of extra) {
          if (!haveIds.has(r.id) && !haveTeams.has(teamKey(r))) rows.push(r);
        }

        out.cricket = sortSportsRows(rows).slice(0, 40);
        metaOut.cricScoreAtMs = now;
        metaOut.cricDay = today;
      } catch (e) {
        console.warn("refreshLiveSports cricket:", e.message);
        out.problems.cricket = String(e.message || e).slice(0, 200);
        if (Array.isArray(prev.cricket)) out.cricket = prev.cricket;
      }
    } else {
      if (Array.isArray(prev.cricket)) out.cricket = prev.cricket;
      if (prevProblems.cricket) out.problems.cricket = prevProblems.cricket;
    }
  }

  // ---- Football (football-data.org v4, 1 call per run) ----
  if (!footKey) {
    out.problems.football = "FOOTBALL_DATA_KEY is not set in functions/.env";
  } else {
    try {
      const from = dhakaDay(now - 24 * 3600 * 1000);
      const to = dhakaDay(now + 24 * 3600 * 1000);
      const j = await sportsGetJson(
        `https://api.football-data.org/v4/matches?dateFrom=${from}&dateTo=${to}`,
        { "X-Auth-Token": footKey }
      );
      if (j && j.errorCode) throw new Error(`football-data: ${j.message || j.errorCode}`);
      const rows = (Array.isArray(j.matches) ? j.matches : [])
        .map(footballRow)
        .filter((r) => r.status === "LIVE" || dhakaDay(r.startMs || 0) === today);
      out.football = sortSportsRows(rows).slice(0, 60);
    } catch (e) {
      console.warn("refreshLiveSports football:", e.message);
      out.problems.football = String(e.message || e).slice(0, 200);
      if (Array.isArray(prev.football)) out.football = prev.football;
    }
  }

  await ref.set(out);
  if (Object.keys(metaOut).length) await metaRef.set(metaOut, { merge: true });
  return {
    cricket: Array.isArray(out.cricket) ? out.cricket.length : 0,
    football: Array.isArray(out.football) ? out.football.length : 0,
    problems: out.problems,
  };
}

