// =============================================================================
// migrateLevelCurveV3 — ONE-TIME move to the v3 curve (harder after Lv.50).
// Founder only. Everybody above level 50 KEEPS their level: their XP is raised
// to what that level costs on the v3 curve (+ the same share of the current
// level's progress). Levels 1-50 cost the same on both curves → untouched.
// Runs once (marker in _operations; each ID stamped levelCurveV3At).
// =============================================================================
function v2CurveXpToReach(level) {
  let total = 0;
  for (let l = 1; l < level; l++) total += v2CurveXpForNextLevel(l);
  return total;
}
function v2CurveLevelFromXp(xp) {
  let level = 1, total = 0;
  const safe = Math.max(0, xp);
  while (level < 100000) {
    const next = total + v2CurveXpForNextLevel(level);
    if (next > safe) break;
    total = next;
    level++;
  }
  return level;
}

exports.migrateLevelCurveV3 = functionsV1
  .runWith({ timeoutSeconds: 540, memory: "1GB" })
  .https.onCall(async (data, context) => {
    const callerUid = requireAuth(context);
    const callerSnap = await db.collection("users").doc(callerUid).get();
    if (!isMainFounderName(callerSnap.get("username"))) {
      throw new functionsV1.https.HttpsError("permission-denied", "Only the founder can run this.");
    }
    const markerRef = db.collection("_operations").doc("level_curve_v3_migration");
    const marker = await markerRef.get();
    if (marker.exists && marker.get("done") === true) {
      return { alreadyDone: true, changed: marker.get("changed") || 0, scanned: marker.get("scanned") || 0 };
    }
    let scanned = 0;
    let changed = 0;
    let last = null;
    while (true) {
      let query = db.collection("users").orderBy(FieldPath.documentId()).limit(400);
      if (last) query = query.startAfter(last);
      const snap = await query.get();
      if (snap.empty) break;
      const batch = db.batch();
      let writes = 0;
      for (const doc of snap.docs) {
        scanned++;
        if (doc.get("levelCurveV3At")) continue; // already moved
        const xp = luckyToNumber(doc.get("xp"));
        const stored = Math.floor(Number(doc.get("level"))) || 1;
        const level = Math.max(stored, v2CurveLevelFromXp(xp));
        if (level <= 50) continue; // same cost on both curves
        const oldStart = v2CurveXpToReach(level);
        const progress = Math.min(Math.max((xp - oldStart) / v2CurveXpForNextLevel(level), 0), 0.999);
        const newXp = xpToReachLevelServer(level) + Math.floor(progress * luckyXpForNextLevel(level));
        const badge = luckyBadgeForLevel(level);
        batch.update(doc.ref, {
          xp: newXp,
          level,
          levelBadgeIcon: badge.icon,
          levelBadgeName: badge.name,
          unlockedGifts: luckyUnlockedGifts(level),
          levelCurveV3At: FieldValue.serverTimestamp(),
        });
        writes++;
        changed++;
      }
      if (writes > 0) await batch.commit();
      last = snap.docs[snap.docs.length - 1];
    }
    await markerRef.set({ done: true, changed, scanned, by: callerUid, at: FieldValue.serverTimestamp() });
    console.log("migrateLevelCurveV3", { scanned, changed });
    return { alreadyDone: false, changed, scanned };
  });

// ✏️ founderEditShopItem — miglife ONLY. Rename / re-price one Style Studio
// color or Entry Effect, or reset it to the built-in name and price.
// data: { kind: "color" | "fx", id, name?, price?, reset? }
exports.founderEditShopItem = functionsV1.https.onCall(async (data, context) => {
  await assertSecretOpen(context && context.auth);   // 🔒 miGlife secret must be open
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can edit the shop.");
  const kind = String(data?.kind || "");
  const id = String(data?.id || "");
  const field = kind === "color" ? "colors" : kind === "fx" ? "entryFx" : kind === "song" ? "profileSong" : null;
  if (!field) throw new E("invalid-argument", "kind must be color, fx or song.");
  const known = kind === "color" ? Object.prototype.hasOwnProperty.call(COLOR_SHOP_CATALOG, id)
    : kind === "song" ? Object.prototype.hasOwnProperty.call(PROFILE_SONG_SHOP, id)
    : Object.prototype.hasOwnProperty.call(ENTRY_FX_SHOP, id);
  if (!known) throw new E("invalid-argument", "Unknown item.");
  // Built-in values (Entry Effect names live only in the app, so the app sends
  // the name it shows when there is no edited name yet).
  const baseName = kind === "color" ? COLOR_SHOP_CATALOG[id].name
    : kind === "song" ? (PROFILE_SONG_NAMES[id] || id)
    : String(data?.currentName || "").trim().slice(0, 30) || id;
  const basePrice = kind === "color" ? COLOR_SHOP_CATALOG[id].price : kind === "song" ? PROFILE_SONG_SHOP[id] : ENTRY_FX_SHOP[id];
  const ref = SHOP_OVERRIDES_REF();
  return db.runTransaction(async (tx) => {
    const snap = await tx.get(ref);
    const all = (snap.exists && snap.get(field)) || {};
    const cur = all[id] || {};
    const curName = typeof cur.name === "string" && cur.name ? cur.name : baseName;
    const curPrice = Number.isInteger(cur.price) && cur.price > 0 ? cur.price : basePrice;
    const history = Array.isArray(cur.history) ? cur.history.slice(-9) : [];
    // 🗑 Delete / ↩ Restore an Entry Effect: a deleted one is hidden from the
    // shop and can't be bought (owners keep it until their 30 days end).
    if (typeof data?.hidden === "boolean") {
      if (kind !== "fx") throw new E("invalid-argument", "Only Entry Effects can be deleted here.");
      tx.set(ref, { [field]: { [id]: { hidden: data.hidden } }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid }, { merge: true });
      return { ok: true, hidden: data.hidden };
    }
    if (data?.reset === true) {
      // ↺ Reset = go back to the value BEFORE the last change, and remember the
      // one it replaced, so pressing Reset again goes forward to it (it switches
      // between the last two): 7,00,000 → 9,00,000 → 10,00,000, then Reset →
      // 9,00,000, Reset → 10,00,000, Reset → 9,00,000 …
      const prev = history.pop();
      if (!prev) return { ok: true, reset: true, name: curName, price: curPrice, nothing: true };
      history.push({ name: curName, price: curPrice });
      tx.set(ref, { [field]: { [id]: { name: prev.name, price: prev.price, history } }, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
      return { ok: true, reset: true, name: prev.name, price: prev.price };
    }
    const name = String(data?.name ?? "").trim();
    const price = Number(data?.price);
    if (!name || name.length > 30) throw new E("invalid-argument", "Name: 1–30 characters.");
    if (!Number.isInteger(price) || price < 1000 || price > 100000000) throw new E("invalid-argument", "Price: a whole number from 1,000 to 100,000,000.");
    if (name === curName && price === curPrice) return { ok: true, name, price, unchanged: true };
    history.push({ name: curName, price: curPrice });   // saved for Reset
    tx.set(ref, { [field]: { [id]: { name, price, history } }, updatedAt: FieldValue.serverTimestamp(), updatedBy: uid }, { merge: true });
    return { ok: true, name, price };
  });
});

// ===========================================================================
// 🗑 DELETE MY ACCOUNT (Google Play: account deletion must be available in the
// app and on the web — web.miglife.app/delete-account).
//   requestAccountDeletion → the account is deleted after ACCOUNT_DELETE_DAYS
//     (Settings → Delete account in the app and on the web). Never for miglife /
//     a founder. Coins left on the account are lost (Google Play: deleting must
//     not be blocked). Every phone / browser is signed out.
//   cancelAccountDeletion  → signing in again within those days cancels it
//     (only a NEW sign-in counts — an old open session can't cancel).
//   processAccountDeletions (hourly) → deletes the due accounts: profile,
//     photos, private data, friends, mail, alerts, tags, coin history and the
//     login. Old room / private chat messages stay, shown as "Deleted user".
// The schedule lives in account_deletions/{uid} (server only, no client rule).
// ===========================================================================
const ACCOUNT_DELETE_DAYS = 7;
const DELETED_USER_NAME = "Deleted user";

async function accountDeletionBlocker(uid, snap) {
  const name = String((snap && snap.get("username")) || "");
  if (isMigwithOnly(name) || (await db.collection("founders").doc(uid).get()).exists) {
    return "The founder account can't be deleted.";
  }
  // (coins no longer block it — they are lost with the account; the app says so first)
  return null;
}

exports.requestAccountDeletion = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  if (String((data && data.confirm) || "") !== "DELETE") throw new E("invalid-argument", "Type DELETE to confirm.");
  const snap = await db.collection("users").doc(uid).get();
  if (!snap.exists) throw new E("not-found", "Account not found.");
  const blocker = await accountDeletionBlocker(uid, snap);
  if (blocker) throw new E("failed-precondition", blocker);
  const scheduledAt = Timestamp.fromMillis(Date.now() + ACCOUNT_DELETE_DAYS * 24 * 60 * 60 * 1000);
  await db.collection("account_deletions").doc(uid).set({
    uid,
    status: "scheduled",
    requestedAt: Timestamp.now(),
    scheduledAt,
  });
  // sign out everywhere (each phone / browser drops off within the hour)
  await getAuth().revokeRefreshTokens(uid).catch((e) => console.error("revokeRefreshTokens", e?.message));
  return { ok: true, scheduledAt: scheduledAt.toMillis(), days: ACCOUNT_DELETE_DAYS };
});

exports.cancelAccountDeletion = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const ref = db.collection("account_deletions").doc(uid);
  const doc = await ref.get();
  if (!doc.exists || doc.get("status") !== "scheduled") return { cancelled: false };
  const authTimeMs = Number(context.auth.token?.auth_time || 0) * 1000;
  const requestedMs = doc.get("requestedAt")?.toMillis?.() || 0;
  // only a sign-in AFTER the request cancels it
  if (authTimeMs <= requestedMs) return { cancelled: false, scheduledAt: doc.get("scheduledAt")?.toMillis?.() || 0 };
  await ref.delete();
  return { cancelled: true };
});

// 🗑 miglife (secret → Delete Account) acts on an email request from
// web.miglife.app/delete-account: schedule (deleted after 7 days — the person
// logging in again cancels it), cancel, or look at the status.
exports.founderAccountDeletion = functionsV1.https.onCall(async (data, context) => {
  await assertSecretOpen(context && context.auth);   // 🔒 miGlife secret must be open
  const callerUid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const caller = await db.collection("users").doc(callerUid).get();
  if (!isMigwithOnly(String(caller.get("username") || ""))) throw new E("permission-denied", "Only miglife can do this.");
  const target = await findUserDocByUsername(String((data && data.username) || "").trim().replace(/^@/, ""));
  if (!target) throw new E("not-found", "User not found.");
  const name = String(target.get("username") || "");
  const ref = db.collection("account_deletions").doc(target.id);
  const action = String((data && data.action) || "status");
  if (action === "cancel") {
    await ref.delete();
    return { username: name, status: "none" };
  }
  if (action === "schedule") {
    const blocker = await accountDeletionBlocker(target.id, target);
    if (blocker) throw new E("failed-precondition", `@${name}: ${blocker}`);
    const scheduledAt = Timestamp.fromMillis(Date.now() + ACCOUNT_DELETE_DAYS * 24 * 60 * 60 * 1000);
    await ref.set({ uid: target.id, status: "scheduled", requestedAt: Timestamp.now(), scheduledAt, by: "miglife" });
    await getAuth().revokeRefreshTokens(target.id).catch(() => {});
    return { username: name, status: "scheduled", scheduledAt: scheduledAt.toMillis() };
  }
  const doc = await ref.get();
  return {
    username: name,
    status: doc.exists ? String(doc.get("status") || "scheduled") : "none",
    scheduledAt: doc.exists ? doc.get("scheduledAt")?.toMillis?.() || 0 : 0,
    coins: coinInt(target.get("balance")),
  };
});

// Runs `fn(batch, doc)` for every doc of these query results, 400 per batch.
async function batchEach(snaps, fn) {
  const docs = snaps.flatMap((s) => (s ? s.docs : []));
  for (let i = 0; i < docs.length; i += 400) {
    const batch = db.batch();
    docs.slice(i, i + 400).forEach((d) => fn(batch, d));
    await batch.commit();
  }
  return docs.length;
}

async function deleteAccountData(uid) {
  const userRef = db.collection("users").doc(uid);
  const snap = await userRef.get();
  const name = String((snap.exists && snap.get("username")) || "").trim();
  const q = (col, field, value) => db.collection(col).where(field, "==", value).get().catch(() => null);

  if (name) {
    // 💬 room messages stay, as "Deleted user" (enter / left lines go)
    const rooms = await db.collection("room_messages").listDocuments();
    for (const room of rooms) {
      const mine = await room.collection("messages").where("senderUid", "==", uid).get().catch(() => null);
      await batchEach([mine], (b, d) => {
        const type = String(d.get("type") || "chat");
        if (type === "room_entry" || type === "room_leave") return b.delete(d.ref);
        const text = String(d.get("text") || "");
        const prefix = `${name}:`;
        b.update(d.ref, {
          sender: DELETED_USER_NAME,
          text: text.startsWith(prefix) ? `${DELETED_USER_NAME}:${text.slice(prefix.length)}` : text,
        });
      });
    }
    // 🔒 private chats stay for the other person, the name goes
    await batchEach([await q("private_messages", "fromUsername", name)], (b, d) =>
      b.update(d.ref, { fromUsername: DELETED_USER_NAME, fromUid: "" }));
    await batchEach([await q("private_messages", "toUsername", name)], (b, d) =>
      b.update(d.ref, { toUsername: DELETED_USER_NAME }));
    await batchEach([await q("gift_activity", "fromUsername", name)], (b, d) => b.update(d.ref, { fromUsername: DELETED_USER_NAME }));
    await batchEach([await q("gift_activity", "toUsername", name)], (b, d) => b.update(d.ref, { toUsername: DELETED_USER_NAME }));
    await batchEach([await q("gift_activity_private", "fromUsername", name)], (b, d) => b.update(d.ref, { fromUsername: DELETED_USER_NAME }));
    await batchEach([await q("gift_activity_private", "toUsername", name)], (b, d) => b.update(d.ref, { toUsername: DELETED_USER_NAME }));
    await batchEach([await q("alerts", "fromUsername", name)], (b, d) => b.update(d.ref, { fromUsername: DELETED_USER_NAME }));
    // ✉️ mail I sent stays in the other person's mailbox, without my name
    await batchEach([await q("emails", "fromUsername", name)], (b, d) =>
      d.get("mailboxUsername") === name ? null : b.update(d.ref, { fromUsername: DELETED_USER_NAME, fromUid: "" }));
    // 💔 my friends are told my account is gone (onFriendshipDeleted reads these marks)
    await batchEach([await q("friend_requests", "fromUsername", name), await q("friend_requests", "toUsername", name)], (b, d) =>
      d.get("status") === "accepted" ? b.set(unfriendMark(d.id), { by: name, reason: "account_deleted", handled: false, at: FieldValue.serverTimestamp() }) : null);
    // gone completely
    await batchEach(
      await Promise.all([
        q("friend_requests", "fromUsername", name), q("friend_requests", "toUsername", name),
        q("alerts", "toUsername", name), q("emails", "mailboxUsername", name),
        q("mentor_requests", "fromUsername", name),
        q("mentor_tagged", "taggedUsername", name), q("mentor_tagged", "mentorUsername", name),
        q("merchant_tagged", "taggedUsername", name), q("merchant_tagged", "merchantUsername", name),
        q("mentor_merchants", "merchantUsername", name), q("mentor_merchants", "mentorUsername", name),
      ]),
      (b, d) => b.delete(d.ref)
    );
    await db.collection("entry_fx_public").doc(name.toLowerCase()).delete().catch(() => {});
  }

  // per-person documents
  for (const col of ["users_private", "achievements", "special_colors", "ludo_inventory", "lb_inventory", "entry_fx",
    "tp_inventory", "tn_inventory", "trivia_scores", "chat_rate", "lucky_user_state", "room_counts", "report_rate",
    "user_blocks", "profile_details"]) {
    await db.collection(col).doc(uid).delete().catch(() => {});
  }
  await db.recursiveDelete(db.collection("user_ip_logs").doc(uid)).catch(() => {});

  // 🖼 profile + cover photos
  try {
    const bucket = require("firebase-admin/storage").getStorage().bucket();
    await Promise.all([`profile_pictures/${uid}.jpg`, `cover_pictures/${uid}.jpg`].map((p) =>
      bucket.file(p).delete({ ignoreNotFound: true }).catch(() => {})));
  } catch (e) {
    console.error("deleteAccountData storage", e?.message);
  }

  // the profile with its coin / XP history, then the login itself
  await db.recursiveDelete(userRef);
  await getAuth().deleteUser(uid).catch((e) => {
    if (e?.code !== "auth/user-not-found") throw e;
  });
}

exports.processAccountDeletions = functionsV1
  .runWith({ timeoutSeconds: 540, memory: "512MB" })
  .pubsub.schedule("every 60 minutes")
  .onRun(async () => {
    const due = await db.collection("account_deletions")
      .where("scheduledAt", "<=", Timestamp.now()).limit(20).get();
    for (const d of due.docs) {
      if (d.get("status") !== "scheduled") continue;
      const uid = d.id;
      try {
        const snap = await db.collection("users").doc(uid).get();
        const blocker = snap.exists ? await accountDeletionBlocker(uid, snap) : null;
        if (blocker) {
          // coins arrived meanwhile (or now a founder): not deleted, request dropped
          await d.ref.delete();
          await alertUser(String(snap.get("username") || ""),
            `ℹ️ Your account was NOT deleted: ${blocker}`, "account_deletion").catch(() => {});
          continue;
        }
        await deleteAccountData(uid);
        await d.ref.set({ uid, status: "deleted", deletedAt: Timestamp.now() });
      } catch (e) {
        console.error("processAccountDeletions", uid, e?.message);
      }
    }
    return null;
  });


// ===========================================================================
// 🚩 REPORTS — Google Play's rule for chat apps: anyone can report a user, a
// room line, a private message or a photo, and the team acts on it.
// ===========================================================================
// reportContent        any signed-in user → reports/{id} (status "open").
//                      The reported text / photo is read HERE from the real
//                      message, so a report can't put words in someone's mouth.
//                      At most REPORTS_PER_DAY per person per day.
// moderationReports    miglife, or a founder miglife gave the "reports"
//                      permission: list | resolve | dismiss.
// reports/{id} is never read or written by phones/browsers (rules: no access).

const REPORT_KINDS = ["user", "room_message", "private_message", "room", "blog_post"];
const REPORT_REASONS = ["spam", "harassment", "hate", "sexual", "violence", "scam", "underage", "impersonation", "other"];
const REPORTS_PER_DAY = 20;

async function hasBlocked(uid, username) {
  try {
    // 🔒 the block list lives in user_blocks/{uid} now (only its owner reads
    // it); an account not moved yet still has it on users/{uid}
    const [blocks, snap] = await Promise.all([
      db.collection("user_blocks").doc(String(uid)).get(),
      db.collection("users").doc(String(uid)).get(),
    ]);
    const list = [...(blocks.get("names") || []), ...(snap.get("blockedUsers") || [])];
    const n = String(username || "").trim().toLowerCase();
    return list.some((b) => String(b).trim().toLowerCase() === n);
  } catch (e) {
    return false;
  }
}

// Only miglife decides who reads reports: miglife, or a founder miglife gave
// the "Reports" tool (miglife secret → Founders). Admin / Staff no longer get it
// automatically.
async function canHandleReports(uid) {
  const snap = await db.collection("users").doc(uid).get();
  const name = String(snap.get("username") || "");
  if (isMigwithOnly(name)) return { ok: true, name };
  return { ok: await hasFounderPerm(uid, "reports", name), name };
}

exports.reportContent = onCallV2({ region: FUNCTIONS_REGION }, async (request) => {
  const uid = requireAuthV2(request);
  const d = request.data || {};
  const kind = REPORT_KINDS.includes(String(d.kind)) ? String(d.kind) : "user";
  const reason = REPORT_REASONS.includes(String(d.reason)) ? String(d.reason) : "other";
  const details = String(d.details || "").trim().slice(0, 1000);
  const roomId = String(d.roomId || "").trim().slice(0, 120);
  const messageId = String(d.messageId || "").trim().slice(0, 200);
  let target = String(d.targetUsername || "").trim().slice(0, 40);

  const meSnap = await db.collection("users").doc(uid).get();
  const me = String(meSnap.get("username") || "");

  // the real message, read on the server
  let messageText = "";
  let imageUrl = "";
  if (kind === "room_message") {
    if (!roomId || !messageId) throw new HttpsErrorV2("invalid-argument", "Which message?");
    const m = await db.collection("room_messages").doc(roomId).collection("messages").doc(messageId).get();
    if (!m.exists) throw new HttpsErrorV2("not-found", "That message is gone.");
    target = String(m.get("sender") || target);
    messageText = String(m.get("text") || "").slice(0, 2000);
    imageUrl = String(m.get("imageUrl") || "").slice(0, 1000);
  } else if (kind === "private_message") {
    if (!messageId) throw new HttpsErrorV2("invalid-argument", "Which message?");
    const m = await db.collection("private_messages").doc(messageId).get();
    if (!m.exists) throw new HttpsErrorV2("not-found", "That message is gone.");
    // only a message sent TO you can be reported by you
    if (String(m.get("toUsername") || "").toLowerCase() !== me.toLowerCase()) {
      throw new HttpsErrorV2("permission-denied", "You can report only messages sent to you.");
    }
    target = String(m.get("fromUsername") || target);
    messageText = String(m.get("text") || "").slice(0, 2000);
    imageUrl = String(m.get("imageUrl") || "").slice(0, 1000);
  } else if (kind === "room") {
    if (!roomId) throw new HttpsErrorV2("invalid-argument", "Which room?");
  } else if (kind === "blog_post") {
    // 📝 a blog post: messageId = the post id
    if (!messageId) throw new HttpsErrorV2("invalid-argument", "Which post?");
    const p = await db.collection("blog_posts").doc(messageId).get();
    if (!p.exists) throw new HttpsErrorV2("not-found", "That post is gone.");
    target = String(p.get("author") || target);
    messageText = `${String(p.get("title") || "")}\n\n${String(p.get("body") || "")}`.slice(0, 2000);
    imageUrl = String(p.get("cover") || p.get("firstImage") || "").slice(0, 1000);
  }
  if (kind !== "room" && !target) throw new HttpsErrorV2("invalid-argument", "Who are you reporting?");
  if (target && target.toLowerCase() === me.toLowerCase()) {
    throw new HttpsErrorV2("invalid-argument", "You can't report yourself.");
  }
  const targetUid = target ? await uidForUsername(target) : null;
  if (target && !targetUid && kind === "user") throw new HttpsErrorV2("not-found", "User not found.");

  // daily limit (Bangladesh day), kept in report_rate/{uid}
  const day = Math.floor((Date.now() + 6 * 3600 * 1000) / 86400000);
  const rateRef = db.collection("report_rate").doc(uid);
  // the same message twice → one report
  const reportRef = messageId
    ? db.collection("reports").doc(`${uid}_${kind}_${messageId}`.replace(/[/]/g, "_").slice(0, 400))
    : db.collection("reports").doc();
  const created = await db.runTransaction(async (tx) => {
    const [rate, existing] = await Promise.all([tx.get(rateRef), tx.get(reportRef)]);
    if (existing.exists) return false;
    const n = rate.exists && rate.get("day") === day ? Number(rate.get("n") || 0) : 0;
    if (n >= REPORTS_PER_DAY) {
      throw new HttpsErrorV2("resource-exhausted", "You have sent many reports today. Please try again tomorrow.");
    }
    tx.set(rateRef, { day, n: n + 1 });
    tx.set(reportRef, {
      kind,
      reason,
      details,
      targetUsername: target,
      targetUid: targetUid || "",
      roomId,
      messageId,
      messageText,
      imageUrl,
      reporterUid: uid,
      reporterUsername: me,
      status: "open",
      createdAt: FieldValue.serverTimestamp(),
    });
    return true;
  });
  // 🔔 tell the team (never undoes the report)
  if (created) {
    try {
      await alertReportHandlers({ reportId: reportRef.id, kind, reason, target, roomId, reporter: me });
    } catch (e) {
      console.error("reportContent: team alert failed", e?.message);
    }
  }
  return { ok: true };
});

// 🚩 A new report → an Alert (+ phone push) for miglife and every founder given
// the "reports" tool (the same people who can open the Reports page). The web push comes from
// webPushOnAlert, which opens miglife secret → Reports.
const REPORT_REASON_LABELS = {
  spam: "Spam", harassment: "Harassment", hate: "Hate speech", sexual: "Sexual content",
  violence: "Violence", scam: "Scam", underage: "Under 18", impersonation: "Impersonation", other: "Other",
};
async function alertReportHandlers({ reportId, kind, reason, target, roomId, reporter }) {
  const people = new Map(); // uid → username
  for (const name of MAIN_FOUNDER_USERNAMES) {
    const uid = await uidForUsername(name);
    if (uid) people.set(uid, name);
  }
  const founders = await db.collection("founders").where("perms", "array-contains", "reports").get();
  await Promise.all(founders.docs.map(async (f) => {
    if (people.has(f.id)) return;
    const u = await db.collection("users").doc(f.id).get();
    const name = String(u.get("username") || "").trim();
    if (name) people.set(f.id, name);
  }));
  // the reporter doesn't need an alert about their own report
  for (const [uid, name] of people) if (name.toLowerCase() === String(reporter).toLowerCase()) people.delete(uid);
  if (!people.size) return;

  const what = kind === "room" ? `room ${roomId}`
    : kind === "user" ? target
    : kind === "private_message" ? `${target}'s private message`
    : kind === "blog_post" ? `${target}'s Feed post`
    : `${target}'s message${roomId ? ` in ${roomId}` : ""}`;
  const message = `🚩 New report: ${what} (${REPORT_REASON_LABELS[reason] || "Other"})`;

  const batch = db.batch();
  for (const name of people.values()) {
    batch.set(db.collection("alerts").doc(), {
      toUsername: name,
      fromUsername: "miGlife",
      type: "report",
      reportId,
      message,
      read: false,
      createdAt: FieldValue.serverTimestamp(),
    });
  }
  await batch.commit();

  // phone push (the app shows it like any other alert)
  await Promise.all([...people.keys()].map(async (uid) => {
    try {
      const token = await fcmTokenOf(uid);
      if (!token) return;
      await getMessaging().send({
        token,
        data: { type: "report", title: "🚩 New report", body: message },
        android: { priority: "high" },
      });
    } catch (e) {
      console.error("report push failed", uid, e?.message);
    }
  }));
}

exports.moderationReports = onCallV2({ region: FUNCTIONS_REGION }, async (request) => {
  const uid = requireAuthV2(request);
  const who = await canHandleReports(uid);
  if (!who.ok) throw new HttpsErrorV2("permission-denied", "Only the miGlife team can see reports.");
  const d = request.data || {};
  const action = String(d.action || "list");
  if (action === "list") {
    const status = String(d.status || "open") === "closed" ? ["resolved", "dismissed"] : ["open"];
    const snap = await db.collection("reports").where("status", "in", status).limit(300).get();
    const ms = (t) => (t && typeof t.toMillis === "function" ? t.toMillis() : 0);
    const reports = snap.docs
      .map((r) => {
        const x = r.data();
        return {
          id: r.id,
          kind: x.kind,
          reason: x.reason,
          details: x.details || "",
          targetUsername: x.targetUsername || "",
          roomId: x.roomId || "",
          messageText: x.messageText || "",
          imageUrl: x.imageUrl || "",
          reporterUsername: x.reporterUsername || "",
          status: x.status,
          note: x.note || "",
          handledBy: x.handledBy || "",
          createdAt: ms(x.createdAt),
          handledAt: ms(x.handledAt),
        };
      })
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 150);
    return { reports };
  }
  if (action === "resolve" || action === "dismiss") {
    const id = String(d.id || "");
    if (!id) throw new HttpsErrorV2("invalid-argument", "Which report?");
    const ref = db.collection("reports").doc(id);
    const r = await ref.get();
    if (!r.exists) throw new HttpsErrorV2("not-found", "Report not found.");
    await ref.update({
      status: action === "resolve" ? "resolved" : "dismissed",
      note: String(d.note || "").trim().slice(0, 500),
      handledBy: who.name,
      handledAt: FieldValue.serverTimestamp(),
    });
    return { ok: true };
  }
  throw new HttpsErrorV2("invalid-argument", "Unknown action.");
});

// =============================================================================
// 📣 PUSH TO EVERYONE — miglife only (miglife secret → Push Notifications)
// =============================================================================
// push_campaigns/{id}: { title, body, kind: "daily" | "once", time: "HH:MM"
// (Bangladesh time, daily), at (ms, once), active, lastSentDay, sentAt, ... }.
// Only the server reads / writes it (founderPushCampaign below). Every 5
// minutes sendDuePushCampaigns sends what is due to every phone (app push
// token) and every browser that turned push on. A campaign is marked as sent
// BEFORE it is sent, so a retry never sends it twice.
const PUSH_CAMPAIGNS = () => db.collection("push_campaigns");
const DHAKA_OFFSET_MS = 6 * 60 * 60 * 1000;
function dhakaParts(ms) {
  const d = new Date(ms + DHAKA_OFFSET_MS);
  return {
    day: d.toISOString().slice(0, 10),
    minutes: d.getUTCHours() * 60 + d.getUTCMinutes(),
  };
}
function pushTimeMinutes(hhmm) {
  const m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(hhmm || ""));
  return m ? Number(m[1]) * 60 + Number(m[2]) : -1;
}
function cleanCampaign(id, d) {
  return {
    id,
    title: String(d.title || ""),
    body: String(d.body || ""),
    kind: d.kind === "daily" ? "daily" : "once",
    time: String(d.time || ""),
    at: Number(d.at || 0),
    active: d.active !== false,
    lastSentDay: String(d.lastSentDay || ""),
    sentAt: Number(d.sentAtMs || 0),
    lastSentCount: Number(d.lastSentCount || 0),
  };
}

// Sends one notification to every app phone and every push-enabled browser.
async function sendPushToEveryone(title, body) {
  const t = String(title || "miGlife").slice(0, 100);
  const b = String(body || "").slice(0, 240);
  const messages = [];
  const owners = []; // [uid, kind, token]
  let cursor = null;
  for (;;) {
    let q = db.collection("users_private").orderBy(FieldPath.documentId()).select("fcmToken", "webPushTokens").limit(500);
    if (cursor) q = q.startAfter(cursor);
    const page = await q.get();
    if (page.empty) break;
    for (const doc of page.docs) {
      const app = String(doc.get("fcmToken") || "").trim();
      if (app) {
        // data-only + high priority: the app's own handler shows it (same as
        // the other pushes), also while the app is closed.
        messages.push({ token: app, data: { type: "broadcast", title: t, body: b }, android: { priority: "high" } });
        owners.push([doc.id, "app", app]);
      }
      const web = doc.get("webPushTokens");
      if (Array.isArray(web)) {
        for (const w of web) {
          if (typeof w !== "string" || !w) continue;
          messages.push({
            token: w,
            webpush: {
              notification: { title: t, body: b, icon: `${WEB_SITE_URL}/icon-192.png`, badge: `${WEB_SITE_URL}/badge-96.png` },
              fcmOptions: { link: `${WEB_SITE_URL}/` },
            },
          });
          owners.push([doc.id, "web", w]);
        }
      }
    }
    cursor = page.docs[page.docs.length - 1];
    if (page.size < 500) break;
  }
  let sent = 0;
  const deadApp = new Set();
  const deadWeb = new Map();
  for (let i = 0; i < messages.length; i += 500) {
    const chunk = messages.slice(i, i + 500);
    const res = await getMessaging().sendEach(chunk);
    res.responses.forEach((r, j) => {
      if (r.success) { sent += 1; return; }
      const code = r.error?.code || "";
      if (code !== "messaging/registration-token-not-registered" && code !== "messaging/invalid-registration-token") return;
      const [uid, kind, token] = owners[i + j];
      if (kind === "app") deadApp.add(uid);
      else deadWeb.set(uid, [...(deadWeb.get(uid) || []), token]);
    });
  }
  // Tokens the phones / browsers threw away are forgotten.
  await Promise.all([
    ...[...deadApp].map((uid) => userPrivateRef(uid).update({ fcmToken: FieldValue.delete() }).catch(() => {})),
    ...[...deadWeb].map(([uid, list]) => userPrivateRef(uid).update({ webPushTokens: FieldValue.arrayRemove(...list) }).catch(() => {})),
  ]);
  return { sent, total: messages.length };
}

exports.founderPushCampaign = functionsV1.runWith({ timeoutSeconds: 300 }).https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can send notifications to everyone.");
  const action = String((data && data.action) || "list");

  if (action === "list") {
    const snap = await PUSH_CAMPAIGNS().orderBy("createdAt", "desc").limit(50).get();
    return { campaigns: snap.docs.map((d) => cleanCampaign(d.id, d.data() || {})) };
  }

  const id = String((data && data.id) || "").trim();
  if (action === "delete") {
    if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) throw new E("invalid-argument", "Bad id.");
    await PUSH_CAMPAIGNS().doc(id).delete();
    return { ok: true };
  }
  if (action === "toggle") {
    if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) throw new E("invalid-argument", "Bad id.");
    await PUSH_CAMPAIGNS().doc(id).set({ active: data.active === true, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
    return { ok: true };
  }

  const title = String((data && data.title) || "").trim().slice(0, 100);
  const body = String((data && data.body) || "").trim().slice(0, 240);
  if (!title || !body) throw new E("invalid-argument", "Write a title and a message.");

  if (action === "sendNow") {
    const r = await sendPushToEveryone(title, body);
    await PUSH_CAMPAIGNS().add({
      title, body, kind: "once", at: Date.now(), active: false,
      sentAtMs: Date.now(), lastSentCount: r.sent, createdBy: uid, createdAt: FieldValue.serverTimestamp(),
    });
    return { ok: true, ...r };
  }

  if (action === "save") {
    const kind = data.kind === "daily" ? "daily" : "once";
    const doc = { title, body, kind, active: true, updatedAt: FieldValue.serverTimestamp() };
    if (kind === "daily") {
      const time = String(data.time || "");
      if (pushTimeMinutes(time) < 0) throw new E("invalid-argument", "Time: HH:MM (Bangladesh time).");
      doc.time = time;
    } else {
      const at = Number(data.at || 0);
      if (!Number.isFinite(at) || at < Date.now() - 60000 || at > Date.now() + 366 * 24 * 3600 * 1000) {
        throw new E("invalid-argument", "Pick a date and time in the future.");
      }
      doc.at = at;
      doc.sentAtMs = 0;
    }
    if (id) {
      if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) throw new E("invalid-argument", "Bad id.");
      await PUSH_CAMPAIGNS().doc(id).set(doc, { merge: true });
      return { ok: true, id };
    }
    const ref = await PUSH_CAMPAIGNS().add({ ...doc, lastSentDay: "", createdBy: uid, createdAt: FieldValue.serverTimestamp() });
    return { ok: true, id: ref.id };
  }
  throw new E("invalid-argument", "Unknown action.");
});

exports.sendDuePushCampaigns = functionsV1
  .runWith({ timeoutSeconds: 300 })
  .pubsub.schedule("every 5 minutes")
  .timeZone("Asia/Dhaka")
  .onRun(async () => {
    const now = Date.now();
    const { day, minutes } = dhakaParts(now);
    const snap = await PUSH_CAMPAIGNS().where("active", "==", true).get();
    for (const doc of snap.docs) {
      const d = doc.data() || {};
      // Claim it first (in a transaction), then send: never twice.
      const claimed = await db.runTransaction(async (tx) => {
        const fresh = await tx.get(doc.ref);
        const f = fresh.data() || {};
        if (f.active !== true) return false;
        if (f.kind === "daily") {
          const at = pushTimeMinutes(f.time);
          // due from its time until 30 minutes after (a late run still sends)
          if (at < 0 || f.lastSentDay === day || minutes < at || minutes - at > 30) return false;
          tx.update(doc.ref, { lastSentDay: day });
          return true;
        }
        const at = Number(f.at || 0);
        if (!at || Number(f.sentAtMs || 0) > 0 || now < at) return false;
        // a once-push more than 6 hours late is dropped, not sent
        tx.update(doc.ref, { sentAtMs: now, active: false });
        return now - at <= 6 * 3600 * 1000;
      });
      if (!claimed) continue;
      try {
        const r = await sendPushToEveryone(d.title, d.body);
        await doc.ref.update({ lastSentCount: r.sent, lastSentAtMs: Date.now() });
        console.log("sendDuePushCampaigns: sent", { id: doc.id, ...r });
      } catch (err) {
        console.error("sendDuePushCampaigns: send failed", doc.id, err);
      }
    }
    return null;
  });


// =============================================================================
// 🔒 PROFILE LOCK (Settings › Privacy › Profile lock) — kept by the SERVER.
// Someone who locked their profile can be messaged in private chat only by
// their FRIENDS, or by a person they wrote to first (a real message, not a
// gift). The Firestore rules check three small marker docs, all written only
// here, so a modified phone can't get around it:
//   profile_locks/{usernameLower}            exists = that person is locked
//   friendships/{a__b}                       exists = a and b are friends (sorted, lowercase)
//   chat_spoke/{a__b}__{speakerLower}        exists = speaker wrote in that chat
// =============================================================================
// profile details that only friends may see when the profile is locked
const PROFILE_DETAIL_FIELDS = ["fullName", "dateOfBirth", "bio", "relationship", "coverPhotoUrl"];
const chatPairKey = (a, b) => [String(a || "").trim().toLowerCase(), String(b || "").trim().toLowerCase()].sort().join("__");
const lockedChatText = (name) => `🔒 Only friends can send private messages. Add ${name} as a friend first.`;

async function privateChatLocked(from, to) {
  // 🤝 Private chat is for FRIENDS only. miglife may write to anyone, and
  // whoever miglife wrote to may answer (chat_spoke).
  const f = String(from || "").trim().toLowerCase();
  const t = String(to || "").trim().toLowerCase();
  if (!f || !t || f === t) return false;
  if (isMainFounderName(f)) return false;
  const pair = chatPairKey(f, t);
  const [friends, spoke] = await Promise.all([
    db.collection("friendships").doc(pair).get(),
    isMainFounderName(t) ? db.collection("chat_spoke").doc(`${pair}__${t}`).get() : null,
  ]);
  return !friends.exists && !(spoke && spoke.exists);
}

// Settings switch → users/{uid}.profileLocked + the profile_locks marker
// (a phone may no longer write profileLocked itself).
exports.setProfileLock = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const locked = data && data.locked === true;
  const ref = db.collection("users").doc(uid);
  const snap = await ref.get();
  const name = String(snap.get("username") || "").trim().toLowerCase();
  if (!name) throw new functionsV1.https.HttpsError("failed-precondition", "No MIG ID on this account.");
  await ref.set({ profileLocked: locked }, { merge: true });
  const lockRef = db.collection("profile_locks").doc(name);
  if (locked) await lockRef.set({ uid, at: FieldValue.serverTimestamp() });
  else await lockRef.delete();
  return { ok: true, locked };
});

// Friend request accepted / removed → friendships marker.
async function refreshFriendship(a, b) {
  if (!a || !b) return;
  const col = db.collection("friend_requests");
  const [x, y] = await Promise.all([
    col.where("fromUsername", "==", a).where("toUsername", "==", b).where("status", "==", "accepted").limit(1).get(),
    col.where("fromUsername", "==", b).where("toUsername", "==", a).where("status", "==", "accepted").limit(1).get(),
  ]);
  const ref = db.collection("friendships").doc(chatPairKey(a, b));
  if (!x.empty || !y.empty) await ref.set({ a: String(a), b: String(b), at: FieldValue.serverTimestamp() });
  else await ref.delete();
}
exports.syncFriendshipMarker = functionsV1.firestore
  .document("friend_requests/{requestId}")
  .onWrite(async (change) => {
    const d = (change.after.exists ? change.after.data() : change.before.data()) || {};
    const before = change.before.exists ? change.before.get("status") : null;
    const after = change.after.exists ? change.after.get("status") : null;
    // only an accepted friendship starting or ending matters
    if (before !== "accepted" && after !== "accepted") return null;
    try {
      await refreshFriendship(String(d.fromUsername || "").trim(), String(d.toUsername || "").trim());
    } catch (e) {
      console.error("syncFriendshipMarker failed", e?.message);
    }
    return null;
  });

// ---------------------------------------------------------------- 🎡 Daily Free Spin
// One free spin per account per DAY — a new spin opens at 12 midnight
// (Bangladesh time) for everyone (miglife; it was "24 h from the last spin"). The app
// / web show the wheel when they open (while a spin is waiting; "Later" just
// closes it). The server picks the slice and an amount inside that slice's
// range, pays it and remembers when in daily_spin/{uid} (server-only), so
// nobody can spin early or choose the result. miglife can change the slices in app_settings/daily_spin
// ({ enabled, slices: [{ min, max, weight }] }) — weights are relative.
const DAILY_SPIN_SLICES = [
  { min: 500, max: 550, weight: 200 },
  { min: 1000, max: 1100, weight: 140 },
  { min: 2000, max: 2200, weight: 80 },
  { min: 3000, max: 3300, weight: 45 },
  { min: 500, max: 550, weight: 200 },
  { min: 5000, max: 5500, weight: 60 },
  { min: 1000, max: 1100, weight: 140 },
  { min: 2000, max: 2200, weight: 80 },
  { min: 3000, max: 3300, weight: 45 },
  { min: 20000, max: 25000, weight: 10, jackpot: true },
];

async function dailySpinConfig() {
  const snap = await db.collection("app_settings").doc("daily_spin").get().catch(() => null);
  const d = (snap && snap.exists && snap.data()) || {};
  const custom = Array.isArray(d.slices) ? d.slices
    .map((x) => ({ min: Math.floor(Number(x.min)), max: Math.floor(Number(x.max)), weight: Number(x.weight), jackpot: x.jackpot === true }))
    .filter((x) => x.min > 0 && x.max >= x.min && x.max <= 10000000 && x.weight > 0) : [];
  return { enabled: d.enabled !== false, slices: custom.length >= 2 && custom.length <= 16 ? custom : DAILY_SPIN_SLICES };
}

// 🕛 one spin per Bangladesh day: a spin made today blocks until the next 12 midnight
const DAILY_SPIN_TZ_MS = 6 * 3600 * 1000;
function dailySpinNextMidnight(ms) {
  const day = 24 * 3600 * 1000;
  return Math.floor((ms + DAILY_SPIN_TZ_MS) / day) * day + day - DAILY_SPIN_TZ_MS;
}
/** true while a spin made at lastMs still blocks (same Bangladesh day as now) */
function dailySpinBlocks(lastMs, nowMs) {
  return lastMs > 0 && dhakaDayKey(lastMs) === dhakaDayKey(nowMs);
}

// when this account last spun (ms), from daily_spin/{uid}
function dailySpinLastMs(snap) {
  if (!snap.exists) return 0;
  const ms = Number(snap.get("atMs") || 0);
  if (ms > 0) return ms;
  const at = snap.get("at");
  return at && typeof at.toMillis === "function" ? at.toMillis() : 0;
}

exports.dailySpin = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const action = String((data && data.action) || "status");
  const { enabled, slices } = await dailySpinConfig();
  const spinRef = db.collection("daily_spin").doc(uid);
  const shown = slices.map((x) => ({ min: x.min, max: x.max, jackpot: !!x.jackpot }));
  const now = Date.now();
  const cur = await spinRef.get();
  const lastMs = dailySpinLastMs(cur);
  const waiting = dailySpinBlocks(lastMs, now);
  const nextAt = waiting ? dailySpinNextMidnight(now) : 0;
  const last = waiting ? { slice: Number(cur.get("slice") || 0), amount: Number(cur.get("amount") || 0) } : null;
  // spunToday = "not spinnable yet" (the apps' old name for it); nextAt = when the next spin opens
  if (action !== "spin") return { enabled, spunToday: waiting, nextAt: waiting ? nextAt : 0, last, slices: shown };
  if (!enabled) throw new E("failed-precondition", "Daily Spin is closed right now.");
  if (!waiting) {
    // the slice: weighted, server-random
    const total = slices.reduce((a, x) => a + x.weight, 0);
    let r = crypto.randomInt(0, Math.max(1, Math.round(total * 1000))) / 1000;
    let slice = slices.length - 1;
    for (let i = 0; i < slices.length; i++) {
      if (r < slices[i].weight) { slice = i; break; }
      r -= slices[i].weight;
    }
    const amount = crypto.randomInt(slices[slice].min, slices[slice].max + 1);
    const txId = `daily_spin_${uid}_${now}`;
    // claim the spin first (one per day even if two phones tap at once)
    const claimed = await db.runTransaction(async (tx) => {
      const [c, u] = await Promise.all([tx.get(spinRef), tx.get(db.collection("users").doc(uid))]);
      if (!u.exists) throw new E("failed-precondition", "No profile on this account.");
      if (u.get("accountSuspended") === true) throw new E("permission-denied", "Your account is suspended.");
      const prev = dailySpinLastMs(c);
      if (dailySpinBlocks(prev, Date.now())) {
        return { slice: Number(c.get("slice") || 0), amount: Number(c.get("amount") || 0), txId: String(c.get("txId") || ""), atMs: prev, already: true };
      }
      tx.set(spinRef, {
        uid, slice, amount, jackpot: !!slices[slice].jackpot, txId, atMs: now, day: dhakaDayKey(now),
        at: FieldValue.serverTimestamp(),
      });
      return { slice, amount, txId, atMs: now, already: false };
    });
    // pay (idempotent: a retry never pays twice)
    if (claimed.txId) {
      await grCredit(uid, claimed.amount, claimed.txId, {
        type: "daily_spin", source: "daily_spin",
        reason: `🎡 Daily spin reward${slices[claimed.slice] && slices[claimed.slice].jackpot ? " — 💎 JACKPOT" : ""}`,
      });
    }
    return { ok: true, slice: claimed.slice, amount: claimed.amount, already: claimed.already, nextAt: dailySpinNextMidnight(claimed.atMs), slices: shown };
  }
  // already spun today: make sure it was paid (a failed payment is paid now)
  const txId = String(cur.get("txId") || "");
  if (txId) await grCredit(uid, last.amount, txId, { type: "daily_spin", source: "daily_spin", reason: "🎡 Daily spin reward" });
  return { ok: true, slice: last.slice, amount: last.amount, already: true, nextAt, slices: shown };
});

// ---------------------------------------------------------------- 💔 Unfriend
// Who ended a friendship is kept in unfriend_logs (miglife only), and the other
// person gets a "friend_removed" alert. The web / app remove friends through
// unfriendUser; a friendship deleted any other way (an older app deleting the
// doc itself, an account deleted) is caught by onFriendshipDeleted.
function unfriendMark(requestId) { return db.collection("_operations").doc(`unfriend_${requestId}`); }
function unfriendAlert(batch, to, from, message) {
  batch.set(db.collection("alerts").doc(), {
    toUsername: to, fromUsername: from, message, type: "friend_removed", read: false, createdAt: FieldValue.serverTimestamp(),
  });
}

exports.unfriendUser = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const target = String((data && data.username) || "").trim();
  if (!target) throw new E("invalid-argument", "Who do you want to remove?");
  const me = String((await db.collection("users").doc(uid).get()).get("username") || "").trim();
  if (!me) throw new E("failed-precondition", "No MIG ID on this account.");
  const col = db.collection("friend_requests");
  const [fromMe, toMe] = await Promise.all([
    col.where("fromUsername", "==", me).where("status", "==", "accepted").get(),
    col.where("toUsername", "==", me).where("status", "==", "accepted").get(),
  ]);
  const k = target.toLowerCase();
  const docs = [
    ...fromMe.docs.filter((d) => String(d.get("toUsername") || "").trim().toLowerCase() === k),
    ...toMe.docs.filter((d) => String(d.get("fromUsername") || "").trim().toLowerCase() === k),
  ];
  if (!docs.length) throw new E("failed-precondition", `${target} is not in your friends list.`);
  const first = docs[0];
  const other = String(first.get("fromUsername") || "").trim().toLowerCase() === me.toLowerCase()
    ? String(first.get("toUsername") || "").trim() : String(first.get("fromUsername") || "").trim();
  const batch = db.batch();
  docs.forEach((d) => {
    batch.set(unfriendMark(d.id), { by: me, reason: "removed", handled: true, at: FieldValue.serverTimestamp() });
    batch.delete(d.ref);
  });
  batch.set(db.collection("unfriend_logs").doc(), {
    byUsername: me, byUid: uid, otherUsername: other, how: "removed", via: String((data && data.via) || "").slice(0, 20),
    at: FieldValue.serverTimestamp(),
  });
  unfriendAlert(batch, other, me, `💔 ${me} removed you from friends.`);
  await batch.commit();
  return { ok: true, username: other };
});

exports.onFriendshipDeleted = functionsV1.firestore
  .document("friend_requests/{requestId}")
  .onDelete(async (snap, context) => {
    const d = snap.data() || {};
    if (d.status !== "accepted") return null;
    const a = String(d.fromUsername || "").trim();
    const b = String(d.toUsername || "").trim();
    if (!a || !b) return null;
    const markSnap = await unfriendMark(context.params.requestId).get();
    const mark = markSnap.exists ? markSnap.data() : null;
    if (mark && mark.handled) return null; // unfriendUser already logged it and told them
    if (!mark) {
      // a Full Reset of friends in the last 3 hours → nobody "removed" anybody
      const reset = await db.collection("_operations").doc("full_reset_friends").get();
      const at = reset.exists && reset.get("at") ? reset.get("at").toMillis() : 0;
      if (Date.now() - at < 3 * 3600 * 1000) return null;
    }
    const by = mark ? String(mark.by || "") : "";
    const how = mark ? String(mark.reason || "removed") : "removed (older app — who is unknown)";
    const batch = db.batch();
    batch.set(db.collection("unfriend_logs").doc(), {
      byUsername: by || null, otherUsername: by ? (by.toLowerCase() === a.toLowerCase() ? b : a) : null,
      a, b, how, requestId: context.params.requestId, at: FieldValue.serverTimestamp(),
    });
    if (by) {
      const other = by.toLowerCase() === a.toLowerCase() ? b : a;
      unfriendAlert(batch, other, by, how === "account_deleted"
        ? `💔 ${by} deleted their account — removed from your friends.`
        : `💔 ${by} removed you from friends.`);
    } else {
      // an older app deleted it: either of the two did — tell both
      unfriendAlert(batch, a, b, `💔 You and ${b} are no longer friends.`);
      unfriendAlert(batch, b, a, `💔 You and ${a} are no longer friends.`);
    }
    await batch.commit();
    return null;
  });

// Someone wrote a real message (not a gift line) → they "spoke" in that chat,
// so the other person may answer even if the writer is locked.
exports.markChatSpoke = functionsV1.firestore
  .document("private_messages/{messageId}")
  .onCreate(async (snap) => {
    const d = snap.data() || {};
    if (String(d.messageType || "") === "gift") return null;
    const from = String(d.fromUsername || "").trim().toLowerCase();
    const to = String(d.toUsername || "").trim().toLowerCase();
    if (!from || !to) return null;
    const ref = db.collection("chat_spoke").doc(`${chatPairKey(from, to)}__${from}`);
    try {
      const cur = await ref.get();
      if (!cur.exists) await ref.set({ at: FieldValue.serverTimestamp() });
    } catch (e) {
      console.error("markChatSpoke failed", e?.message);
    }
    return null;
  });

// Once a day (and once by hand right after deploying — Cloud Scheduler →
// "Force run"): rebuild every marker from the real data, so the friendships
// and locks made BEFORE this feature are there too.
exports.syncPrivacyMarkers = functionsV1.runWith({ timeoutSeconds: 540, memory: "1GB" }).pubsub
  .schedule("every 24 hours")
  .timeZone("Asia/Dhaka")
  .onRun(async () => {
    // 🔒 locks
    const locked = await db.collection("users").where("profileLocked", "==", true).get();
    const lockedNames = new Set();
    for (const u of locked.docs) {
      const name = String(u.get("username") || "").trim().toLowerCase();
      if (!name) continue;
      lockedNames.add(name);
      await db.collection("profile_locks").doc(name).set({ uid: u.id, at: FieldValue.serverTimestamp() }, { merge: true });
    }
    const oldLocks = await db.collection("profile_locks").get();
    for (const l of oldLocks.docs) if (!lockedNames.has(l.id)) await l.ref.delete();
    // 🤝 friendships
    const pairs = new Map();
    let last = null;
    for (;;) {
      let q = db.collection("friend_requests").where("status", "==", "accepted").orderBy(FieldPath.documentId()).limit(500);
      if (last) q = q.startAfter(last);
      const page = await q.get();
      if (page.empty) break;
      page.docs.forEach((d) => {
        const a = String(d.get("fromUsername") || "").trim();
        const b = String(d.get("toUsername") || "").trim();
        if (a && b) pairs.set(chatPairKey(a, b), { a, b });
      });
      last = page.docs[page.docs.length - 1];
      if (page.size < 500) break;
    }
    const keys = [...pairs.keys()];
    for (let i = 0; i < keys.length; i += 400) {
      const batch = db.batch();
      keys.slice(i, i + 400).forEach((k) => batch.set(db.collection("friendships").doc(k), { ...pairs.get(k), at: FieldValue.serverTimestamp() }, { merge: true }));
      await batch.commit();
    }
    const oldPairs = await db.collection("friendships").get();
    for (const p of oldPairs.docs) if (!pairs.has(p.id)) await p.ref.delete();
    // 🔒 users/{uid} is readable by every signed-in person, so the private
    // bits move out of it: the block list → user_blocks/{uid} (owner only),
    // and the profile details → profile_details/{uid} (hidden from
    // non-friends when the profile is locked).
    let movedUsers = 0;
    let lastUser = null;
    for (;;) {
      let q = db.collection("users").orderBy(FieldPath.documentId()).limit(20);
      if (lastUser) q = q.startAfter(lastUser);
      const page = await q.get();
      if (page.empty) break;
      // a batch holds at most 500 writes: this one commits itself every 400
      // (one person may have visited hundreds of profiles)
      const pending = [];
      let current = db.batch();
      let ops = 0;
      const bump = () => {
        if (++ops >= 400) {
          pending.push(current.commit());
          current = db.batch();
          ops = 0;
        }
      };
      const batch = {
        set: (...a) => { current.set(...a); bump(); },
        update: (...a) => { current.update(...a); bump(); },
        commit: async () => { pending.push(current.commit()); await Promise.all(pending); },
      };
      let n = 0;
      for (const u of page.docs) {
        const d = u.data() || {};
        const name = String(d.username || "").trim().toLowerCase();
        const hasBlocks = Array.isArray(d.blockedUsers);
        const hasDetails = PROFILE_DETAIL_FIELDS.some((k) => d[k] !== undefined);
        const hasVisits = Array.isArray(d.visitedProfiles) || d.visitedAt !== undefined;
        const hasVotes = Array.isArray(d.votedProfiles) || d.votedAt !== undefined;
        if (!hasBlocks && !hasDetails && !hasVisits && !hasVotes) continue;
        const clear = {};
        // 👣 ❤️ footprints / votes: profile_visits|profile_votes/{whoLower}/by/{myUid}
        const moveList = (list, times, sub) => {
          (Array.isArray(list) ? list : []).map(String).filter(Boolean).forEach((who) => {
            const key = who.trim().toLowerCase();
            if (!key || key === name) return;
            const t = times && times[key];
            batch.set(db.collection(sub).doc(key).collection("by").doc(u.id), {
              username: String(d.username || ""),
              at: t && typeof t.toMillis === "function" ? t : FieldValue.serverTimestamp(),
            }, { merge: true });
          });
        };
        if (hasVisits && name) {
          moveList(d.visitedProfiles, d.visitedAt, "profile_visits");
          clear.visitedProfiles = FieldValue.delete();
          clear.visitedAt = FieldValue.delete();
        }
        if (hasVotes && name) {
          moveList(d.votedProfiles, d.votedAt, "profile_votes");
          clear.votedProfiles = FieldValue.delete();
          clear.votedAt = FieldValue.delete();
        }
        if (hasBlocks) {
          if (d.blockedUsers.length) {
            batch.set(db.collection("user_blocks").doc(u.id),
              { names: FieldValue.arrayUnion(...d.blockedUsers.map(String)), updatedAt: FieldValue.serverTimestamp() }, { merge: true });
          }
          clear.blockedUsers = FieldValue.delete();
        }
        if (hasDetails && name) {
          const details = { usernameLower: name, updatedAt: FieldValue.serverTimestamp() };
          PROFILE_DETAIL_FIELDS.forEach((k) => {
            if (d[k] !== undefined) {
              details[k] = d[k];
              clear[k] = FieldValue.delete();
            }
          });
          batch.set(db.collection("profile_details").doc(u.id), details, { merge: true });
        }
        if (Object.keys(clear).length) {
          batch.update(u.ref, clear);
          n++;
        }
      }
      if (n) await batch.commit();
      movedUsers += n;
      lastUser = page.docs[page.docs.length - 1];
      if (page.size < 20) break;
    }
    console.log(`syncPrivacyMarkers: ${movedUsers} accounts' block list / details / footprints / votes made private`);

    // 🎁 private-chat gifts written before gift_activity_private existed → move them
    let moved = 0;
    for (;;) {
      const page = await db.collection("gift_activity").where("context", "==", "private_chat").limit(400).get();
      if (page.empty) break;
      const batch = db.batch();
      page.docs.forEach((d) => {
        batch.set(db.collection("gift_activity_private").doc(d.id), d.data());
        batch.delete(d.ref);
      });
      await batch.commit();
      moved += page.size;
      if (page.size < 400) break;
    }
    console.log(`syncPrivacyMarkers: ${lockedNames.size} locked, ${pairs.size} friendships, ${moved} private gifts moved`);
    return null;
  });

// 🤝 How many friends a profile has (Profile page). friend_requests can only
// be read by its own two people, so other profiles' counts come from here —
// just the number, never the names.
exports.getFriendCount = functionsV1.https.onCall(async (data, context) => {
  requireAuth(context);
  const name = String((data && data.username) || "").trim();
  if (!name || name.length > 64) throw new functionsV1.https.HttpsError("invalid-argument", "Username is missing.");
  const col = db.collection("friend_requests");
  const [out, inc] = await Promise.all([
    col.where("fromUsername", "==", name).where("status", "==", "accepted").select("toUsername").get(),
    col.where("toUsername", "==", name).where("status", "==", "accepted").select("fromUsername").get(),
  ]);
  const names = new Set([
    ...out.docs.map((d) => String(d.get("toUsername") || "").trim().toLowerCase()),
    ...inc.docs.map((d) => String(d.get("fromUsername") || "").trim().toLowerCase()),
  ]);
  names.delete("");
  // 👣 ❤️ only the NUMBERS of footprints and votes (who = the owner only)
  const [footprints, voters] = await Promise.all([
    achCountArray("visitedProfiles", name).catch(() => 0),
    achCountArray("votedProfiles", name).catch(() => 0),
  ]);
  return { count: names.size, footprints, voters };
});

// =====================================================================
// 🎂 BIRTHDAYS — everyone who added a birthday (Edit Profile) is wished by
// miGlife on the day, automatically:
//   • 12:00 AM Bangladesh time: birthdayDaily finds today's birthdays, saves
//     birthdays/{yyyy-MM-dd} and sends each one a Birthday Card (alert).
//   • When the app / web opens: getTodayBirthdays → the popup (the birthday
//     person sees their own wish; everyone else ONE popup for all of them).
//   • sendBirthdayWish → "X wished you a happy birthday" alert (once a day).
// Only the day and month are used; the year / age is never shown.
// Everyone sees every birthday (a birthday on the profile is enough), and the
// birthday ID shows in the 🎂 birthday colour for the whole day (24 hours):
// the apps read birthdays/{date}.names (rules: signed-in users may read).
// =====================================================================
const BIRTHDAY_LIST_MAX = 50;
// 🔒 One birthday a year per ID: changing the date again and again never gives
// a second wish / colour. birthday_log/{uid}.lastDate = the last celebrated day.
const BIRTHDAY_MIN_GAP_DAYS = 330;
const daysBetween = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86400000);

// "yyyy-MM-dd" (or "dd-MM-yyyy", "dd/MM/yyyy") → "MM-dd", or "".
function birthdayMonthDay(raw) {
  const s = String(raw || "").trim();
  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
  if (m) return `${m[2].padStart(2, "0")}-${m[3].padStart(2, "0")}`;
  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (m) return `${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
  return "";
}

// The month-days celebrated on this date (29 Feb is celebrated on 28 Feb in
// a year without one).
function birthdayKeysFor(date) {
  const md = date.slice(5);
  const year = Number(date.slice(0, 4));
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  return md === "02-28" && !leap ? ["02-28", "02-29"] : [md];
}

async function buildBirthdaysFor(date) {
  const keys = birthdayKeysFor(date);
  const byUid = new Map(); // uid -> true
  const [details, legacy] = await Promise.all([
    db.collection("profile_details").select("dateOfBirth").get(),
    db.collection("users").where("dateOfBirth", ">", "").select("dateOfBirth").get().catch(() => ({ docs: [] })),
  ]);
  // profile_details wins; users.dateOfBirth only for accounts not moved yet
  const fromDetails = new Set();
  details.docs.forEach((d) => {
    fromDetails.add(d.id);
    if (keys.includes(birthdayMonthDay(d.get("dateOfBirth")))) byUid.set(d.id, true);
  });
  legacy.docs.forEach((d) => {
    if (!fromDetails.has(d.id) && keys.includes(birthdayMonthDay(d.get("dateOfBirth")))) byUid.set(d.id, true);
  });
  let uids = Array.from(byUid.keys());
  // skip anyone already celebrated in the last BIRTHDAY_MIN_GAP_DAYS days
  const logOf = new Map();
  for (let i = 0; i < uids.length; i += 100) {
    const snaps = await db.getAll(...uids.slice(i, i + 100).map((u) => db.collection("birthday_log").doc(u)));
    snaps.forEach((s) => { if (s.exists) logOf.set(s.id, String(s.get("lastDate") || "")); });
  }
  uids = uids.filter((u) => {
    const last = logOf.get(u);
    if (!last || last === date) return true;
    const gap = daysBetween(last, date);
    return !(gap > 0 && gap < BIRTHDAY_MIN_GAP_DAYS);
  });
  const people = [];
  for (let i = 0; i < uids.length; i += 100) {
    const refs = uids.slice(i, i + 100).map((u) => db.collection("users").doc(u));
    const snaps = await db.getAll(...refs);
    snaps.forEach((s) => {
      if (!s.exists) return;
      const username = String(s.get("username") || "").trim();
      if (!username || s.get("suspended") === true || s.get("banned") === true) return;
      people.push({ uid: s.id, username, locked: s.get("profileLocked") === true });
    });
  }
  people.sort((a, b) => a.username.toLowerCase().localeCompare(b.username.toLowerCase()));
  const names = people.map((p) => p.username.toLowerCase());
  for (let i = 0; i < people.length; i += 400) {
    const batch = db.batch();
    people.slice(i, i + 400).forEach((p) => batch.set(db.collection("birthday_log").doc(p.uid), { lastDate: date, username: p.username, at: FieldValue.serverTimestamp() }, { merge: true }));
    await batch.commit();
  }
  const doc = { date, people, names, createdAt: FieldValue.serverTimestamp() };
  await db.collection("birthdays").doc(date).set(doc);
  return doc;
}

// Today's list, rebuilt when it is more than 10 minutes old — so a birthday
// added during the day still gets its wish, colour and popup that same day.
const BIRTHDAY_REFRESH_MS = 10 * 60 * 1000;
async function birthdaysFor(date) {
  const snap = await db.collection("birthdays").doc(date).get();
  const at = snap.exists ? snap.get("createdAt") : null;
  const fresh = at && typeof at.toMillis === "function" && Date.now() - at.toMillis() < BIRTHDAY_REFRESH_MS;
  if (snap.exists && Array.isArray(snap.get("names")) && fresh) return { date, people: snap.get("people") || [] };
  const built = await buildBirthdaysFor(date); // first call today / stale / the night job missed
  // a new birthday person found by this refresh gets their Birthday Card now
  const before = new Set(((snap.exists && snap.get("people")) || []).map((p) => p.uid));
  const added = built.people.filter((p) => !before.has(p.uid));
  if (added.length) await sendBirthdayCards(date, added);
  return built;
}

async function sendBirthdayCards(date, people) {
  for (const p of people) {
    await alertUser(
      p.username,
      `🎂 Happy Birthday, ${p.username}! Wishing you a wonderful day and a great year ahead. Thank you for being part of miGlife 💖`,
      "birthday",
      { birthdayDate: date },
      `birthday_${date}_${p.uid}`
    );
  }
}

exports.birthdayDaily = functionsV1
  .runWith({ timeoutSeconds: 300 })
  .pubsub.schedule("0 0 * * *")
  .timeZone("Asia/Dhaka")
  .onRun(async () => {
    try {
      const date = dhakaDateString(new Date());
      const { people } = await buildBirthdaysFor(date);
      await sendBirthdayCards(date, people);
      console.log("birthdayDaily", { date, count: people.length });
    } catch (error) {
      console.error("birthdayDaily failed", error?.message);
    }
    return null;
  });

// The popup's list: { date, me: bool, people: [username…] } (me not included).
exports.getTodayBirthdays = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const meSnap = await db.collection("users").doc(uid).get();
  const me = String(meSnap.get("username") || "").trim();
  const date = dhakaDateString(new Date());
  const { people } = await birthdaysFor(date);
  const mine = people.some((p) => p.uid === uid);
  if (mine) {
    // the Birthday Card too, in case the night job had not sent it yet
    const p = people.find((x) => x.uid === uid);
    await sendBirthdayCards(date, [p]);
  }
  const shown = people.filter((p) => p.uid !== uid).slice(0, BIRTHDAY_LIST_MAX);
  return { date, me: mine, people: shown.map((p) => p.username) };
});

// 🎂 "Wish" button → an alert to the birthday person (one per friend per day).
exports.sendBirthdayWish = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const to = String(data?.to || "").trim();
  if (!to) throw new functionsV1.https.HttpsError("invalid-argument", "Who to wish?");
  const meSnap = await db.collection("users").doc(uid).get();
  const me = String(meSnap.get("username") || "").trim();
  if (!me) throw new functionsV1.https.HttpsError("failed-precondition", "No MIG ID on this account.");
  const date = dhakaDateString(new Date());
  const { people } = await birthdaysFor(date);
  const p = people.find((x) => x.username.toLowerCase() === to.toLowerCase());
  if (!p) throw new functionsV1.https.HttpsError("failed-precondition", `It is not ${to}'s birthday today.`);
  if (p.uid === uid) throw new functionsV1.https.HttpsError("invalid-argument", "That's you! 🎂");
  const id = `bdaywish_${date}_${uid}_${p.uid}`;
  const ref = db.collection("alerts").doc(id);
  if ((await ref.get()).exists) return { ok: true, already: true };
  await ref.set({
    toUsername: p.username,
    fromUsername: me,
    message: `🎂 ${me} wished you a happy birthday!`,
    type: "birthday_wish",
    read: false,
    birthdayDate: date,
    createdAt: FieldValue.serverTimestamp(),
  });
  return { ok: true, already: false };
});

// 🧹 Founder tool: a Merchant who became a Mentor is removed from every Merchant
// record (their Mentor's list, their tags, their merchant-source trail, their
// requests) — the same clean-up as changeManagementRole → endMerchantship.
// Dry run by default: {username} lists what would go; {username, apply: true} deletes.
exports.endMerchantshipByName = functionsV1.runWith({ timeoutSeconds: 300 }).https.onCall(async (data, context) => {
  await assertSecretOpen(context && context.auth);   // 🔒 miGlife secret must be open
  const callerUid = requireAuth(context);
  const callerSnap = await db.collection("users").doc(callerUid).get();
  if (!isMainFounderName(callerSnap.get("username"))) {
    throw new functionsV1.https.HttpsError("permission-denied", "Only the founder can end a merchantship.");
  }
  const name = String(data?.username || "").trim();
  if (!name) throw new functionsV1.https.HttpsError("invalid-argument", "username is needed.");
  const [links, mentorTags, myTags, myReqs] = await Promise.all([
    db.collection("mentor_merchants").where("merchantUsername", "==", name).get(),
    db.collection("mentor_tagged").where("taggedUsername", "==", name).get(),
    db.collection("merchant_tagged").where("merchantUsername", "==", name).get(),
    db.collection("merchant_tag_requests").where("merchantUsername", "==", name).get(),
  ]);
  const paths = [
    ...links.docs,
    ...mentorTags.docs.filter((d) => String(d.get("source") || "") === "merchant"),
    ...myTags.docs,
    ...myReqs.docs,
  ].map((d) => d.ref.path);
  if (data?.apply !== true) return { dryRun: true, username: name, count: paths.length, paths };
  await endMerchantship(name);   // deletes the same records and tells the old Mentors
  return { dryRun: false, username: name, count: paths.length, paths };
});

// =============================================================================
// 🎨 STICKER STORE (miglife: "like the video" — All / Free / Paid / My Packs)
// =============================================================================
// sticker_packs/{packId}: { name, category, price (coins, 0 = free), active,
//   sortOrder, stickers: [{ id, url }], urls: [url…], cover, count }
// users/{uid}/sticker_packs/{packId}: a pack this person owns — FOREVER (free
//   ones are claimed, paid ones bought once). Written only here.
// A sticker is sent in a room (room_messages type "sticker") or a private chat
// (private_messages messageType "sticker") with its imageUrl + stickerPack; the
// rules check the sender owns that pack and the picture belongs to it.
const STICKER_MAX_PER_PACK = 40;
const STICKER_MAX_BYTES = 1500 * 1024;
const STICKER_PRICE_MAX = 100000000;
const stickerPackRef = (packId) => db.collection("sticker_packs").doc(packId);
const stickerOwnRef = (uid, packId) => db.collection("users").doc(uid).collection("sticker_packs").doc(packId);
const STICKER_PACK_ID_RE = /^[A-Za-z0-9_-]{3,64}$/;

// 🆓 the starter packs (drawn for miGlife, served by the website)
const STARTER_STICKER_HOST = "https://web.miglife.app/stickers";
const STARTER_STICKER_PACKS = [
  { id: "starter_smiles", name: "miGlife Smiles", category: "Emoji", count: 12, sortOrder: 1 },
  { id: "starter_love", name: "Love & Friends", category: "Love", count: 12, sortOrder: 2 },
  // 🎞 the 100 reaction stickers, animated: "file:MOTION …" (files in /stickers/<id>/)
  { id: "reaction_faces", name: "Faces & Feelings", category: "Animated", sortOrder: 3,
    files: "001_hi:SWAY 002_hello:SWAY 003_smile:BOUNCE 004_love:BEAT 005_laugh:BOUNCE 006_heart:BEAT 007_kiss:BEAT 008_heart_eyes:BEAT 009_blush:FLOAT 010_hug:FLOAT 011_blow_kiss:BEAT 012_happy:BOUNCE 013_wink:BOUNCE 014_joy_tears:BOUNCE 015_laugh_tears:BOUNCE 016_laughing:BOUNCE 017_cry:FLOAT 018_sad_cry:FLOAT 019_sob:FLOAT 020_angry:SHAKE 021_rage:SHAKE 022_upset:SHAKE 023_worried:FLOAT 024_sad:FLOAT 025_cute:POP 026_surprised:SHAKE 027_shocked:SHAKE 028_cool:POP 029_thumbs_up:SWAY 030_sunglasses:WOBBLE 031_sleepy:FLOAT 032_sleeping_boy:FLOAT 033_sleeping_girl:FLOAT 034_sick:FLOAT 035_fever_boy:FLOAT 036_fever_girl:FLOAT 037_broken_heart:BEAT 038_love_boy:BEAT 039_love_girl:BEAT 040_devil:SHAKE" },
  { id: "reaction_love", name: "Love & Words", category: "Animated", sortOrder: 4,
    files: "041_angel_boy:FLOAT 042_angel_girl:FLOAT 043_winged_heart:BEAT 044_rose_bouquet:BEAT 045_rose:BEAT 046_hearts:BEAT 047_heart_hands:BEAT 048_love_text_boy:POP 049_love_text_girl:POP 050_love_word:POP 051_ok_boy:SWAY 052_ok_girl:SWAY 053_thumbs_up_hand:SWAY 054_thumbs_down:SWAY 055_clap:SWAY 056_pray:SWAY 057_thank_you:POP 058_welcome:POP 059_sorry:POP 060_congratulations:POP 061_bye_boy:SWAY 062_bye_girl:SWAY 063_miss_you:POP 064_boy_heart:BEAT 065_girl_heart:BEAT 066_flower_boy:SWAY 067_flower_girl:SWAY 068_beautiful:POP 069_cute:POP 070_cool:POP" },
  { id: "reaction_party", name: "Party, Food & Cute", category: "Animated", sortOrder: 5,
    files: "071_birthday_cake:BOUNCE 072_gift_box:BEAT 073_party_popper:BOUNCE 074_party_face:BOUNCE 075_cake_boy:BOUNCE 076_cake_girl:BOUNCE 077_balloons:BOUNCE 078_fireworks:WOBBLE 079_star:WOBBLE 080_crown:WOBBLE 081_coffee:FLOAT 082_tea:FLOAT 083_pizza:BOUNCE 084_burger:BOUNCE 085_fries:BOUNCE 086_chocolate_heart:BEAT 087_lips:BEAT 088_paw_print:BOUNCE 089_present:BEAT 090_diamond_ring:BEAT 091_cat:BOUNCE 092_puppy:BOUNCE 093_panda:BOUNCE 094_teddy_bear:BOUNCE 095_penguin:BOUNCE 096_unicorn:BOUNCE 097_kiss_lips:BEAT 098_winged_heart_2:BEAT 099_clover:BEAT 100_trophy:WOBBLE" },
];
// ✨ how a sticker moves (drawn by the app / website, the picture stays a PNG)
const STICKER_MOTIONS = ["", "BOUNCE", "BEAT", "SWAY", "POP", "FLOAT", "SHAKE", "WOBBLE"];
const starterStickers = (p) => p.files
  ? p.files.split(" ").map((f) => {
    const [file, motion] = f.split(":");
    return { id: file.slice(0, 3), url: `${STARTER_STICKER_HOST}/${p.id}/${file}.png`, motion: motion || "" };
  })
  : Array.from({ length: p.count }, (_, i) => ({ id: `s${i + 1}`, url: `${STARTER_STICKER_HOST}/${p.id}/${i + 1}.png` }));

// Claim a free pack / buy a paid one with coins. Owned forever.
exports.getStickerPack = functionsV1.https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const packId = String(data?.packId || "").trim();
  if (!STICKER_PACK_ID_RE.test(packId)) throw new E("invalid-argument", "Unknown sticker pack.");
  const operationId = String(data?.operationId || "").trim();
  if (!/^[A-Za-z0-9_-]{8,128}$/.test(operationId)) throw new E("invalid-argument", "Missing operationId.");
  const userRef = db.collection("users").doc(uid);
  const ownRef = stickerOwnRef(uid, packId);
  const opRef = db.collection("_operations").doc(`sticker_${operationId}`);
  return db.runTransaction(async (tx) => {
    const [pack, user, own, op] = await Promise.all([tx.get(stickerPackRef(packId)), tx.get(userRef), tx.get(ownRef), tx.get(opRef)]);
    if (op.exists) return op.data().result || { ok: true };
    if (!pack.exists || pack.get("active") === false) throw new E("not-found", "This sticker pack is not available.");
    if (!user.exists) throw new E("not-found", "User not found.");
    const balance = Number(user.get("balance") || 0);
    if (own.exists) return { ok: true, packId, already: true, balance };
    const price = Math.max(0, Math.floor(Number(pack.get("price") || 0)));
    const name = String(pack.get("name") || "Sticker pack");
    if (price > 0) {
      if (balance < price) throw new E("failed-precondition", `You need ${price.toLocaleString("en-US")} coins for ${name}.`);
      tx.update(userRef, { balance: balance - price, balanceUpdatedAt: FieldValue.serverTimestamp() });
      tx.set(userRef.collection("coin_transactions").doc(`sticker_${operationId}`), {
        type: "purchase", source: "shop", item: `sticker_${packId}`, amount: -price,
        reason: `Sticker pack: ${name}`,
        balanceBefore: balance, balanceAfter: balance - price, operationId, createdAt: FieldValue.serverTimestamp(),
      });
    }
    tx.set(ownRef, { packId, name, price, since: FieldValue.serverTimestamp() });
    const result = { ok: true, packId, price, balance: balance - price };
    tx.create(opRef, { type: "sticker_pack", uid, result, createdAt: FieldValue.serverTimestamp() });
    return result;
  });
});

// ✏️ miglife's sticker admin: save a pack (name / category / price / on-off /
// order), add or remove a sticker picture, and put the starter packs in.
exports.founderStickerPack = functionsV1.runWith({ timeoutSeconds: 60, memory: "512MB" }).https.onCall(async (data, context) => {
  const uid = requireAuth(context);
  const E = functionsV1.https.HttpsError;
  const me = await db.collection("users").doc(uid).get();
  if (!isMainFounderName(me.get("username"))) throw new E("permission-denied", "Only miglife can change sticker packs.");
  const action = String(data?.action || "");
  const clean = (v, max) => String(v || "").replace(/[\u0000-\u001f]/g, "").trim().slice(0, max);

  if (action === "seedStarter") {
    const made = [];
    for (const p of STARTER_STICKER_PACKS) {
      const ref = stickerPackRef(p.id);
      const snap = await ref.get();
      if (snap.exists) continue;   // never overwrite miglife's own edits
      const stickers = starterStickers(p);
      await ref.set({
        name: p.name, category: p.category, price: 0, active: true, sortOrder: p.sortOrder,
        stickers, urls: stickers.map((s) => s.url), cover: stickers[0].url, count: stickers.length,
        createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp(),
      });
      made.push(p.id);
    }
    return { ok: true, made };
  }

  if (action === "save") {
    let packId = String(data?.packId || "").trim();
    const isNew = !packId;
    if (isNew) packId = "sp_" + crypto.randomBytes(6).toString("hex");
    if (!STICKER_PACK_ID_RE.test(packId)) throw new E("invalid-argument", "Unknown sticker pack.");
    const name = clean(data?.name, 40);
    if (!name) throw new E("invalid-argument", "Give the pack a name.");
    const price = Math.floor(Number(data?.price || 0));
    if (!(Number.isInteger(price) && price >= 0 && price <= STICKER_PRICE_MAX)) throw new E("invalid-argument", "Price must be 0 (free) – 100,000,000 coins.");
    const fields = {
      name, category: clean(data?.category, 30), price,
      active: data?.active !== false, sortOrder: Math.floor(Number(data?.sortOrder || 0)) || 0,
      updatedAt: FieldValue.serverTimestamp(),
    };
    if (isNew) Object.assign(fields, { stickers: [], urls: [], cover: "", count: 0, createdAt: FieldValue.serverTimestamp() });
    else if (!(await stickerPackRef(packId).get()).exists) throw new E("not-found", "Unknown sticker pack.");
    await stickerPackRef(packId).set(fields, { merge: true });
    return { ok: true, packId };
  }

  if (action === "addSticker") {
    const packId = String(data?.packId || "").trim();
    if (!STICKER_PACK_ID_RE.test(packId)) throw new E("invalid-argument", "Unknown sticker pack.");
    const contentType = String(data?.contentType || "").toLowerCase();
    if (!/^image\/(png|webp|gif|jpeg)$/.test(contentType)) throw new E("invalid-argument", "Upload a PNG, WebP, GIF or JPG picture.");
    const buf = Buffer.from(String(data?.fileBase64 || ""), "base64");
    if (buf.length < 100) throw new E("invalid-argument", "The picture is empty.");
    if (buf.length > STICKER_MAX_BYTES) throw new E("invalid-argument", "The picture is bigger than 1.5 MB.");
    const ref = stickerPackRef(packId);
    const pack = await ref.get();
    if (!pack.exists) throw new E("not-found", "Unknown sticker pack.");
    const list = Array.isArray(pack.get("stickers")) ? pack.get("stickers") : [];
    if (list.length >= STICKER_MAX_PER_PACK) throw new E("failed-precondition", `A pack can hold ${STICKER_MAX_PER_PACK} stickers.`);
    const ext = contentType.split("/")[1].replace("jpeg", "jpg");
    const sid = "st_" + crypto.randomBytes(5).toString("hex");
    const path = `stickers/${packId}/${sid}.${ext}`;
    const token = crypto.randomUUID();
    const bucket = require("firebase-admin/storage").getStorage().bucket();
    await bucket.file(path).save(buf, {
      resumable: false,
      metadata: { contentType, cacheControl: "public, max-age=31536000", metadata: { firebaseStorageDownloadTokens: token } },
    });
    const url = `https://firebasestorage.googleapis.com/v0/b/${bucket.name}/o/${encodeURIComponent(path)}?alt=media&token=${token}`;
    await db.runTransaction(async (tx) => {
      const cur = await tx.get(ref);
      const stickers = Array.isArray(cur.get("stickers")) ? cur.get("stickers") : [];
      const motion = STICKER_MOTIONS.includes(String(data?.motion || "")) ? String(data?.motion || "") : "";
      const next = [...stickers, { id: sid, url, motion }].slice(0, STICKER_MAX_PER_PACK);
      tx.update(ref, { stickers: next, urls: next.map((s) => s.url), cover: cur.get("cover") || url, count: next.length, updatedAt: FieldValue.serverTimestamp() });
    });
    return { ok: true, packId, id: sid, url };
  }

  // ✨ change how one sticker moves
  if (action === "setMotion") {
    const packId = String(data?.packId || "").trim();
    const sid = String(data?.stickerId || "").trim();
    const motion = String(data?.motion || "");
    if (!STICKER_PACK_ID_RE.test(packId) || !sid) throw new E("invalid-argument", "Unknown sticker.");
    if (!STICKER_MOTIONS.includes(motion)) throw new E("invalid-argument", "Unknown motion.");
    const ref = stickerPackRef(packId);
    await db.runTransaction(async (tx) => {
      const cur = await tx.get(ref);
      if (!cur.exists) throw new E("not-found", "Unknown sticker pack.");
      const stickers = (Array.isArray(cur.get("stickers")) ? cur.get("stickers") : []).map((s) => (s && s.id === sid ? { ...s, motion } : s));
      tx.update(ref, { stickers, updatedAt: FieldValue.serverTimestamp() });
    });
    return { ok: true };
  }

  if (action === "removeSticker") {
    const packId = String(data?.packId || "").trim();
    const sid = String(data?.stickerId || "").trim();
    if (!STICKER_PACK_ID_RE.test(packId) || !sid) throw new E("invalid-argument", "Unknown sticker.");
    const ref = stickerPackRef(packId);
    await db.runTransaction(async (tx) => {
      const cur = await tx.get(ref);
      if (!cur.exists) throw new E("not-found", "Unknown sticker pack.");
      const stickers = (Array.isArray(cur.get("stickers")) ? cur.get("stickers") : []).filter((s) => s && s.id !== sid);
      // (a sticker already sent keeps showing: its picture stays in Storage)
      tx.update(ref, { stickers, urls: stickers.map((s) => s.url), cover: stickers[0]?.url || "", count: stickers.length, updatedAt: FieldValue.serverTimestamp() });
    });
    return { ok: true };
  }

  throw new E("invalid-argument", "Unknown action.");
});

// =====================================================================
// 📰 Feed (was "Blog") — every user may write. One callable, `blog`, with an action:
//   create / edit / delete / like / comment / deleteComment / view
// blog_posts/{id}: authorUid, author, title, body, cover, category, likes,
//   comments, views, hot (Popular order), createdAt, updatedAt
// blog_posts/{id}/comments/{cid}, /likes/{uid}, /views/{uid}
// Everything is written here (the rules let nobody write). Anyone can read.
// =====================================================================
const BLOG_MOODS = ["happy", "loved", "sad", "excited", "thankful", "blessed", "cool", "tired", "inlove", "angry", "sick", "celebrating"];
const BLOG_CATEGORIES = ["life", "games", "music", "fun", "news", "love", "tips", "other"];
const BLOG_POSTS_PER_DAY = 5;
const BLOG_COMMENTS_PER_DAY = 100;
const BLOG_TITLE_MAX = 120;
const BLOG_BODY_MAX = 20000;
const BLOG_COMMENT_MAX = 500;
const BLOG_IMG_PREFIX = "https://firebasestorage.googleapis.com/";
// ↗ share to my wall: the post being shared (one level only — sharing a share shares the original)
async function blogSharedMeta(d) {
  const id = String(d.sharedId || "").trim().slice(0, 100);
  if (!id) return null;
  const E = functionsV1.https.HttpsError;
  let src = await db.collection("blog_posts").doc(id).get();
  if (!src.exists) throw new E("not-found", "That Mig is gone.");
  if (src.get("sharedId")) {
    src = await db.collection("blog_posts").doc(String(src.get("sharedId"))).get();
    if (!src.exists) throw new E("not-found", "That Mig is gone.");
  }
  return {
    sharedId: src.id,
    sharedAuthor: String(src.get("author") || "").slice(0, 60),
    sharedTitle: String(src.get("title") || "").slice(0, 120),
  };
}
// 🎬 the video on/off switch (app_settings/feed.videoEnabled). Missing = on.
async function feedVideoOn() {
  const s = await db.collection("app_settings").doc("feed").get();
  return s.exists ? s.get("videoEnabled") !== false : true;
}

// Popular order: newer posts and more likes / comments / views rise (Reddit-style)
function blogHot(createdMs, likes, comments, views) {
  const score = Math.max(1, likes * 3 + comments * 2 + Math.floor(views / 10));
  return Math.log10(score) + createdMs / 1000 / 45000;
}
function blogImgOk(u) {
  return !u || (typeof u === "string" && u.startsWith(BLOG_IMG_PREFIX) && u.length <= 1000);
}
async function blogCanModerate(uid, name) {
  if (isMigwithOnly(name)) return true;
  const u = await db.collection("users").doc(uid).get();
  const roles = [String(u.get("role") || "").toLowerCase(), ...(u.get("roles") || []).map((r) => String(r).toLowerCase())];
  if (roles.some((r) => ["admin", "staff", "superadmin", "founder"].includes(r))) return true;
  const f = await db.collection("founders").doc(uid).get();
  return f.exists;
}
function blogClean(d) {
  const E = functionsV1.https.HttpsError;
  const title = String(d.title || "").replace(/\s+/g, " ").trim();
  const body = String(d.body || "").replace(/\r/g, "").trim();
  const cover = String(d.cover || "").trim();
  const category = BLOG_CATEGORIES.includes(String(d.category)) ? String(d.category) : "other";
  if (title.length < 3) throw new E("invalid-argument", "Please write a title (at least 3 letters).");
  if (title.length > BLOG_TITLE_MAX) throw new E("invalid-argument", `The title can be at most ${BLOG_TITLE_MAX} letters.`);
  if (!body) throw new E("invalid-argument", "Please write something.");
  if (body.length > BLOG_BODY_MAX) throw new E("invalid-argument", "The post is too long.");
  if (!blogImgOk(cover)) throw new E("invalid-argument", "That cover photo can't be used.");
  // photos inside the post are lines like ![](url)
  const imgs = [...body.matchAll(/!\[\]\(([^)\s]+)\)/g)].map((m) => m[1]);
  if (imgs.length > 10) throw new E("invalid-argument", "At most 10 photos in one post.");
  if (!imgs.every(blogImgOk)) throw new E("invalid-argument", "A photo in the post can't be used.");
  const excerpt = body.replace(/!\[\]\([^)]*\)/g, " ").replace(/\*\*/g, "").replace(/\s+/g, " ").trim().slice(0, 200);
  // 🎨 the Text Art colour the writer picked (0–7, 8 = plain white); left out = keep / pick from the id
  const bg = Number.isInteger(d.bg) && d.bg >= 0 && d.bg < 9 ? d.bg : null;
  // ⚡ a small copy (≈480 px) of the cover for the Feed list; the full photo opens with the post
  const thumb = String(d.thumb || "").trim();
  const thumbOk = thumb && blogImgOk(thumb);
  // 📍 where the writer is ("Cox's Bazar" + "Bangladesh"); sent as "" = no place.
  // Left out (older apps) = keep the post's place as it is.
  const loc = d.place === undefined ? {} : {
    place: String(d.place || "").replace(/\s+/g, " ").trim().slice(0, 60),
    placeSub: String(d.place ? d.placeSub || "" : "").replace(/\s+/g, " ").trim().slice(0, 80),
  };
  // 😊 the writer's mood ("mahin is 😊 happy"): one of BLOG_MOODS, "" = none; left out = kept
  const mood = d.mood === undefined ? {} : { mood: BLOG_MOODS.includes(String(d.mood)) ? String(d.mood) : "" };
  return { title, body, cover, category, excerpt, firstImage: imgs[0] || "", ...(bg === null ? {} : { bg }), ...(thumbOk ? { thumb } : {}), ...loc, ...mood };
}
// 🔔 an alert in the person's migAlerts
function blogAlert(batch, toUsername, fromUsername, postId, message) {
  batch.set(db.collection("alerts").doc(), {
    toUsername, fromUsername, type: "blog", postId, message, read: false,
    createdAt: FieldValue.serverTimestamp(),
  });
}

// @mentions in a Feed post — only the writer's FRIENDS are notified (at most
// 10 per post). A name that is not a friend stays a plain link, no alert.
const BLOG_MENTION_MAX = 10;
async function blogMentionedFriends(me, body) {
  const meLow = me.toLowerCase();
  const names = [...new Set([...String(body).matchAll(/@([A-Za-z0-9_.\-]{2,30})/g)].map((m) => m[1].toLowerCase()))]
    .filter((n) => n !== meLow).slice(0, 40);
  const out = [];
  for (const n of names) {
    if (out.length >= BLOG_MENTION_MAX) break;
    const f = await db.collection("friendships").doc(chatPairKey(meLow, n)).get();
    if (!f.exists) continue;
    const to = await uidForUsername(n);
    if (!to) continue;
    const u = await db.collection("users").doc(to).get();
    out.push({ uid: to, name: String(u.get("username") || n), snap: u });
  }
  return out;
}
// 🔔 alert (migAlerts + website push) and 📱 app push to each newly mentioned friend
async function blogNotifyMentions(me, postId, title, mentioned, alreadyLower) {
  const fresh = mentioned.filter((x) => !alreadyLower.includes(x.name.toLowerCase()));
  if (!fresh.length) return;
  const batch = db.batch();
  const t = String(title || "").slice(0, 60);
  for (const x of fresh) blogAlert(batch, x.name, me, postId, `📰 ${me} mentioned you in a Mig: "${t}"`);
  await batch.commit().catch((e) => console.error("blog mention alerts failed", e?.message));
  await Promise.all(fresh.map(async (x) => {
    try {
      if (await hasBlocked(x.uid, me)) return;
      const token = await fcmTokenOf(x.uid, x.snap);
      if (!token) return;
      await getMessaging().send({
        token,
        data: { type: "blog_mention", title: `📰 ${me} mentioned you`, body: `in a Mig: "${t}"`, postId },
        android: { priority: "high" },
      });
    } catch (e) {
      console.error("blog mention push failed", x.name, e?.message);
    }
  }));
}

// 🔒 Post privacy: 🌍 Everyone posts live in blog_posts (anyone can read them, as
// before). 👥 Friends and 🔒 Only me posts live in blog_private, which the rules let
// NO app or browser read — only this server, which checks who is asking. So old
// apps never see them, and nobody can read them by a trick.
const BLOG_PRIVACY = ["friends", "me"];
function blogPrivacyOf(d) {
  const p = String(d.privacy || "").trim();
  return BLOG_PRIVACY.includes(p) ? p : "";
}
// my friends' names, as written in friendships/{a__b} ({ a, b })
async function blogFriendNames(me) {
  const names = new Set();
  const forms = [...new Set([me, me.toLowerCase()])];
  for (const f of forms) {
    const [x, y] = await Promise.all([
      db.collection("friendships").where("a", "==", f).limit(500).get(),
      db.collection("friendships").where("b", "==", f).limit(500).get(),
    ]);
    x.docs.forEach((s) => names.add(String(s.get("b") || "").trim()));
    y.docs.forEach((s) => names.add(String(s.get("a") || "").trim()));
  }
  names.delete("");
  return [...names];
}
// may this person see this private post? the writer always; friends only for 👥 Friends
async function blogCanSeePrivate(s, uid, me) {
  if (s.get("authorUid") === uid) return true;
  if (s.get("privacy") !== "friends") return false;
  const f = await db.collection("friendships").doc(chatPairKey(me, String(s.get("author") || ""))).get();
  return f.exists;
}
// a post as plain data for the app / web (timestamps → ms)
// 📊 Poll on a Mig: 2–4 answers, open 1 / 3 / 7 days, one answer or several.
// Votes live in {post}/poll_votes/{uid}; the post keeps the counts.
const BLOG_POLL_DAYS = [1, 3, 7];
function blogPollClean(d) {
  const E = functionsV1.https.HttpsError;
  const p = d && d.poll;
  if (!p || typeof p !== "object") return null;
  const seen = new Set();
  const options = (Array.isArray(p.options) ? p.options : [])
    .map((x) => String(x || "").replace(/\s+/g, " ").trim().slice(0, 60))
    .filter((x) => x && !seen.has(x.toLowerCase()) && seen.add(x.toLowerCase()));
  if (options.length < 2) throw new E("invalid-argument", "A poll needs at least 2 answers.");
  if (options.length > 4) throw new E("invalid-argument", "A poll can have at most 4 answers.");
  const days = BLOG_POLL_DAYS.includes(Number(p.days)) ? Number(p.days) : 3;
  return {
    options, counts: options.map(() => 0), total: 0, voters: 0,
    multi: p.multi === true, days, endsMs: Date.now() + days * 86400000, ended: false,
  };
}
const blogPollOpen = (poll) => !!poll && poll.ended !== true && Date.now() < Number(poll.endsMs || 0);

function blogOut(s) {
  const x = { ...s.data() };
  delete x.createdAt;
  delete x.updatedAt;
  return { id: s.id, ...x };
}
// 🔁 move a post (with its likes, comments and views) to the other collection, same id
async function blogMovePost(fromRef, toRef, privacy) {
  const s = await fromRef.get();
  const data = { ...s.data() };
  if (privacy) data.privacy = privacy;
  else delete data.privacy;
  await toRef.set(data);
  const copy = async (from, to, sub) => {
    const docs = (await from.collection(sub).limit(2000).get()).docs;
    for (let i = 0; i < docs.length; i += 400) {
      const b = db.batch();
      docs.slice(i, i + 400).forEach((x) => b.set(to.collection(sub).doc(x.id), x.data()));
      await b.commit();
    }
    return docs;
  };
  await copy(fromRef, toRef, "likes");
  await copy(fromRef, toRef, "views");
  await copy(fromRef, toRef, "poll_votes");
  const comments = await copy(fromRef, toRef, "comments");
  // 👍 each comment's reactions go along too
  for (const c of comments) {
    if (c.get("likes")) await copy(c.ref, toRef.collection("comments").doc(c.id), "likes");
  }
  await db.recursiveDelete(fromRef);
}

exports.blog = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const d = data || {};
  const action = String(d.action || "");
  const meSnap = await db.collection("users").doc(uid).get();
  const me = String(meSnap.get("username") || "").trim();
  if (!me) throw new E("failed-precondition", "Your account is not ready yet.");
  if (meSnap.get("accountSuspended") === true && ["create", "edit", "comment"].includes(action)) {
    throw new E("permission-denied", "Your account is suspended.");
  }
  const day = dhakaDayKey();
  const rateRef = db.collection("blog_rate").doc(uid);
  const postId = String(d.postId || "").trim();
  let postRef = postId ? db.collection("blog_posts").doc(postId.slice(0, 100)) : null;
  // 🔒 the post may be a 👥 Friends / 🔒 Only me one: find it, and check I may see it
  // (one that I may not see is simply "gone" for me)
  const resolvePost = async (pid) => {
    const pub = db.collection("blog_posts").doc(pid);
    if ((await pub.get()).exists) return pub;
    const priv = db.collection("blog_private").doc(pid);
    const ps = await priv.get();
    if (ps.exists && (await blogCanSeePrivate(ps, uid, me))) return priv;
    return pub; // missing → the actions below say "That Mig is gone."
  };

  // 🔖 save / unsave a post for my Saved tab (only I see my saves)
  if (action === "save") {
    const pid = String(d.postId || "").trim().slice(0, 100);
    if (!pid) throw new E("invalid-argument", "Which post?");
    const ref = db.collection("blog_saves").doc(uid + "_" + pid);
    if (d.saved === true) {
      const post = await (await resolvePost(pid)).get();
      if (!post.exists) throw new E("not-found", "That Mig is gone.");
      await ref.set({ uid, postId: pid, at: FieldValue.serverTimestamp() });
    } else {
      await ref.delete();
    }
    return { ok: true, saved: d.saved === true };
  }
  // 🔖 the ids of the posts I saved
  if (action === "saves") {
    const snap = await db.collection("blog_saves").where("uid", "==", uid).limit(300).get();
    return { ok: true, postIds: snap.docs.map((x) => String(x.get("postId") || "")).filter(Boolean) };
  }
  // 😀 who reacted to a post: name + reaction, newest first (everyone can see it, like Facebook)
  if (action === "reactors") {
    const pid = String(d.postId || "").trim().slice(0, 100);
    if (!pid) throw new E("invalid-argument", "Which post?");
    const snap = await (await resolvePost(pid)).collection("likes").limit(300).get();
    const reactors = snap.docs
      .map((x) => ({
        username: String(x.get("username") || x.id).slice(0, 60),
        type: String(x.get("type") || "👍"),
        at: x.get("at") && typeof x.get("at").toMillis === "function" ? x.get("at").toMillis() : 0,
      }))
      .sort((a, b) => b.at - a.at);
    return { ok: true, reactors };
  }
  // 🎼 the song library: songs miGlife added (licensed or royalty-free); anyone can list them
  if (action === "songs") {
    const snap = await db.collection("song_library").orderBy("createdMs", "desc").limit(200).get();
    return {
      ok: true,
      songs: snap.docs.map((x) => ({
        id: x.id,
        title: String(x.get("title") || "Song").slice(0, 60),
        artist: String(x.get("artist") || "").slice(0, 60),
        category: String(x.get("category") || "").slice(0, 20),
        url: String(x.get("url") || ""),
      })),
    };
  }
  if (action === "videoStatus") {
    return { ok: true, videoEnabled: await feedVideoOn() };
  }
  if (action === "story") {
    // 📸 a story = a photo the writer uploaded to blog_stories/{their uid}/..., OR just text (no photo)
    const url = String(d.url || "").trim();
    const text = String(d.text || "").replace(/\s+/g, " ").trim().slice(0, 280);
    const photo = url !== "";
    if (!photo && !text) throw new E("invalid-argument", "Write something or add a photo.");
    if (photo && (!url.startsWith(BLOG_IMG_PREFIX) || url.length > 1000 || !url.includes("blog_stories%2F" + uid + "%2F"))) {
      throw new E("invalid-argument", "That story photo can't be used.");
    }
    // 🎵 an optional song: a short audio file the writer uploaded to blog_music/{their uid}/...
    // (the story plays only the first 30 seconds of it)
    let song = null;
    if (d.song && typeof d.song === "object") {
      const su = String(d.song.url || "").trim();
      const own = su.includes("blog_music%2F" + uid + "%2F");
      const fromLibrary = su.includes("blog_music_library%2F");
      if (!su.startsWith(BLOG_IMG_PREFIX) || su.length > 1000 || !(own || fromLibrary)) {
        throw new E("invalid-argument", "That song can't be used.");
      }
      song = {
        url: su,
        title: String(d.song.title || "").replace(/\s+/g, " ").trim().slice(0, 60) || "Song",
        startSec: Math.max(0, Math.min(600, Number(d.song.startSec) || 0)),
      };
    }
    const now = Date.now();
    const ref = db.collection("blog_stories").doc();
    await ref.set({
      authorUid: uid, author: me, url, song,
      text: photo ? "" : text,
      caption: photo ? String(d.caption || "").replace(/\s+/g, " ").trim().slice(0, 140) : "",
      privacy: ["friends", "only_me"].includes(d.privacy) ? d.privacy : "everyone",
      createdMs: now, expiresAt: now + 24 * 3600 * 1000,
      createdAt: FieldValue.serverTimestamp(),
    });
    return { ok: true, id: ref.id };
  }
  // 📸 my story: change the caption and who can see it, or delete it (only the writer)
  if (action === "storyUpdate" || action === "storyDelete") {
    const sid = String(d.storyId || "").trim().slice(0, 100);
    if (!sid) throw new E("invalid-argument", "Which story?");
    const ref = db.collection("blog_stories").doc(sid);
    const s = await ref.get();
    if (!s.exists) throw new E("not-found", "That story is gone.");
    if (s.get("authorUid") !== uid) throw new E("permission-denied", "You can only change your own story.");
    if (action === "storyDelete") {
      await ref.delete();
      return { ok: true };
    }
    await ref.update({
      caption: String(d.caption || "").replace(/\s+/g, " ").trim().slice(0, 140),
      privacy: ["friends", "only_me"].includes(d.privacy) ? d.privacy : "everyone",
    });
    return { ok: true };
  }
  if (action === "create") {
    const p = blogClean(d);
    // 🎬 optional video: only a file the writer uploaded to blog_videos/{their uid}/...
    const video = String(d.video || "").trim();
    if (video && (!video.startsWith(BLOG_IMG_PREFIX) || video.length > 1000 || !video.includes("blog_videos%2F" + uid + "%2F"))) {
      throw new E("invalid-argument", "That video can't be used.");
    }
    if (video && !(await feedVideoOn())) {
      throw new E("failed-precondition", "Video posts are turned off right now.");
    }
    const privacy = blogPrivacyOf(d);
    const poll = blogPollClean(d);
    // 🔒 Only me: nobody is told; 👥 Friends: tagged friends may see it, so they are told
    const mentioned = privacy === "me" ? [] : await blogMentionedFriends(me, p.body);
    const shared = await blogSharedMeta(d);
    const ref = db.collection(privacy ? "blog_private" : "blog_posts").doc();
    const now = Date.now();
    await db.runTransaction(async (tx) => {
      const rate = await tx.get(rateRef);
      const n = rate.exists && rate.get("day") === day ? Number(rate.get("posts") || 0) : 0;
      if (n >= BLOG_POSTS_PER_DAY) throw new E("resource-exhausted", `You can write ${BLOG_POSTS_PER_DAY} Migs a day. Please come back tomorrow.`);
      const c = rate.exists && rate.get("day") === day ? Number(rate.get("comments") || 0) : 0;
      tx.set(rateRef, { day, posts: n + 1, comments: c });
      tx.set(ref, {
        ...p, video, ...(shared || {}), ...(privacy ? { privacy } : {}), ...(poll ? { poll } : {}), mentions: mentioned.map((x) => x.name), authorUid: uid, author: me, likes: 0, comments: 0, views: 0,
        hot: blogHot(now, 0, 0, 0), createdMs: now,
        createdAt: FieldValue.serverTimestamp(), updatedAt: FieldValue.serverTimestamp(),
      });
    });
    await blogNotifyMentions(me, ref.id, p.title, mentioned, []);
    return { ok: true, postId: ref.id };
  }

  // may I delete other people's posts / comments? (shows 🗑 Delete)
  // ⚡ which reaction I left on each of these posts, in one call (the Feed used to read
  // one likes/{uid} document per post)
  if (action === "myReactions") {
    const ids = (Array.isArray(d.postIds) ? d.postIds : []).map((x) => String(x || "").trim().slice(0, 100)).filter(Boolean).slice(0, 40);
    if (!ids.length) return { ok: true, reactions: {} };
    // 🔒 the ids of 👥 / 🔒 posts in the list are sent as privateIds (they live in blog_private)
    const priv = new Set((Array.isArray(d.privateIds) ? d.privateIds : []).map((x) => String(x || "").trim()));
    const snaps = await db.getAll(...ids.map((id) => db.collection(priv.has(id) ? "blog_private" : "blog_posts").doc(id).collection("likes").doc(uid)));
    const reactions = {};
    snaps.forEach((l, i) => { if (l.exists) reactions[ids[i]] = String(l.get("type") || "👍"); });
    return { ok: true, reactions };
  }

  // 📊 which answers I picked on each of these polls, in one call (like myReactions)
  if (action === "myPollVotes") {
    const ids = (Array.isArray(d.postIds) ? d.postIds : []).map((x) => String(x || "").trim().slice(0, 100)).filter(Boolean).slice(0, 40);
    if (!ids.length) return { ok: true, votes: {} };
    const priv = new Set((Array.isArray(d.privateIds) ? d.privateIds : []).map((x) => String(x || "").trim()));
    const snaps = await db.getAll(...ids.map((id) => db.collection(priv.has(id) ? "blog_private" : "blog_posts").doc(id).collection("poll_votes").doc(uid)));
    const votes = {};
    snaps.forEach((v, i) => { if (v.exists && Array.isArray(v.get("choices"))) votes[ids[i]] = v.get("choices").map(Number); });
    return { ok: true, votes };
  }

  // 🔒 the 👥 Friends / 🔒 Only me posts I may see, newest first:
  //   scope "mine" = only my own; otherwise mine + my friends' 👥 Friends posts
  //   (author = one name: only that member's, if I may see them)
  if (action === "privateFeed") {
    const col = db.collection("blog_private");
    const want = String(d.author || "").trim();
    const out = [];
    const mineToo = !want || want.toLowerCase() === me.toLowerCase();
    if (mineToo) (await col.where("authorUid", "==", uid).limit(60).get()).docs.forEach((x) => out.push(x));
    if (d.scope !== "mine" && !(want && mineToo)) {
      let friends = await blogFriendNames(me);
      if (want) friends = friends.filter((n) => n.toLowerCase() === want.toLowerCase());
      for (let i = 0; i < friends.length && i < 300; i += 30) {
        const snap = await col.where("author", "in", friends.slice(i, i + 30)).where("privacy", "==", "friends").limit(40).get();
        snap.docs.forEach((x) => out.push(x));
      }
    }
    const posts = out.map(blogOut).sort((a, b) => Number(b.createdMs || 0) - Number(a.createdMs || 0)).slice(0, 60);
    return { ok: true, posts };
  }
  // 🔒 one post (Everyone, or a 👥 / 🔒 one I may see) and, for a private one, its comments
  // (the comments of Everyone posts are read straight from blog_posts, as before)
  if (action === "getPost") {
    const pid = String(d.postId || "").trim().slice(0, 100);
    if (!pid) throw new E("invalid-argument", "Which post?");
    const ref = await resolvePost(pid);
    const s = await ref.get();
    if (!s.exists) throw new E("not-found", "That Mig is gone.");
    const out = { ok: true, post: blogOut(s) };
    if (ref.parent.id === "blog_private") {
      const cs = await ref.collection("comments").orderBy("createdAt", "asc").limit(300).get();
      out.comments = cs.docs.map((c) => ({
        id: c.id,
        authorUid: String(c.get("authorUid") || ""),
        author: String(c.get("author") || ""),
        text: String(c.get("text") || ""),
        replyTo: String(c.get("replyTo") || ""),
        reactions: c.get("reactions") || {},
        likes: Number(c.get("likes") || 0),
        createdMs: c.get("createdAt") && typeof c.get("createdAt").toMillis === "function" ? c.get("createdAt").toMillis() : 0,
      }));
    }
    return out;
  }

  // 🌐 Translate a Mig (miglife: "no translate button" — the browser's own
  // translator only works in desktop Chrome, not on phones). The server asks
  // Google Translate (free web endpoint) and keeps the result per post +
  // language + text, so each Mig is translated once per language.
  if (action === "translate") {
    const pid = String(d.postId || "").trim().slice(0, 100);
    if (!pid) throw new E("invalid-argument", "Which post?");
    let to = String(d.to || "en").trim().toLowerCase().split("-")[0];
    if (!/^[a-z]{2,3}$/.test(to)) to = "en";
    const ref = await resolvePost(pid);
    const s = await ref.get();
    if (!s.exists) throw new E("not-found", "That Mig is gone.");
    const plain = (v) => String(v || "").split("\n")
      .filter((l) => !/^!\[\]\(https:\/\/[^)\s]+\)$/.test(l.trim()))
      .join("\n").replace(/\*\*/g, "").trim().slice(0, 4500);
    const title = plain(s.get("title")).slice(0, 300);
    const body = plain(s.get("body"));
    if (!title && !body) throw new E("failed-precondition", "Nothing to translate.");
    const hash = crypto.createHash("sha1").update(title + "\u0000" + body).digest("hex").slice(0, 16);
    const cacheRef = db.collection("blog_translations").doc(`${pid}_${to}`);
    const cached = await cacheRef.get();
    if (cached.exists && cached.get("hash") === hash) {
      return { ok: true, title: cached.get("title") || "", text: cached.get("text") || "", from: cached.get("from") || "", to: cached.get("to") || to };
    }
    const gtx = async (q, tl) => {
      if (!q) return { text: "", from: "" };
      const res = await fetch("https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&dt=t&tl=" + encodeURIComponent(tl), {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
        body: "q=" + encodeURIComponent(q),
      });
      if (!res.ok) throw new Error("translate " + res.status);
      const j = await res.json();
      const text = (Array.isArray(j?.[0]) ? j[0] : []).map((seg) => (Array.isArray(seg) ? String(seg[0] || "") : "")).join("");
      return { text, from: String(j?.[2] || "") };
    };
    let tl = to;
    let out;
    try {
      out = { b: await gtx(body || title, tl) };
      // already in my language → English (or Bangla, if it was English)
      if (out.b.from && out.b.from.split("-")[0] === tl) {
        tl = tl === "en" ? "bn" : "en";
        out.b = await gtx(body || title, tl);
      }
      out.t = body && title ? await gtx(title, tl) : { text: "" };
    } catch (err) {
      console.error("blog translate failed", err);
      throw new E("unavailable", "Couldn't translate right now. Try again.");
    }
    const result = {
      title: body ? out.t.text : out.b.text,
      text: body ? out.b.text : "",
      from: (out.b.from || "").split("-")[0],
      to: tl,
    };
    if (!result.text && !result.title) throw new E("unavailable", "No translation.");
    await cacheRef.set({ ...result, hash, at: FieldValue.serverTimestamp() }).catch(() => {});
    return { ok: true, ...result };
  }

  if (action === "canModerate") {
    return { ok: true, canModerate: await blogCanModerate(uid, me) };
  }

  if (!postRef) throw new E("invalid-argument", "Which post?");
  postRef = await resolvePost(postRef.id);

  // 🔒 change who can see my post: "everyone" | "friends" | "me" (only the writer)
  if (action === "setPrivacy") {
    const next = blogPrivacyOf(d);
    const s = await postRef.get();
    if (!s.exists) throw new E("not-found", "That Mig is gone.");
    if (s.get("authorUid") !== uid) throw new E("permission-denied", "Only the writer can change this.");
    const isPrivate = postRef.parent.id === "blog_private";
    if (!next && isPrivate) {
      await blogMovePost(postRef, db.collection("blog_posts").doc(postRef.id), "");
    } else if (next && !isPrivate) {
      if (s.get("sharedId")) throw new E("failed-precondition", "A shared Mig stays 🌍 Everyone.");
      await blogMovePost(postRef, db.collection("blog_private").doc(postRef.id), next);
    } else if (next) {
      await postRef.update({ privacy: next });
    }
    return { ok: true, privacy: next || "everyone" };
  }

  if (action === "edit") {
    const p = blogClean(d);
    const mentioned = await blogMentionedFriends(me, p.body);
    let before = [];
    await db.runTransaction(async (tx) => {
      const s = await tx.get(postRef);
      if (!s.exists) throw new E("not-found", "That Mig is gone.");
      if (s.get("authorUid") !== uid) throw new E("permission-denied", "Only the writer can edit this Mig.");
      before = Array.isArray(s.get("mentions")) ? s.get("mentions").map((x) => String(x).toLowerCase()) : [];
      // a new cover without a new small copy: the old small copy goes (the list shows the cover)
      const staleThumb = !p.thumb && s.get("thumb") && s.get("cover") !== p.cover ? { thumb: FieldValue.delete() } : {};
      tx.update(postRef, { ...p, ...staleThumb, mentions: mentioned.map((x) => x.name), updatedAt: FieldValue.serverTimestamp(), edited: true });
    });
    // only friends who were not mentioned before get a notification
    await blogNotifyMentions(me, postId, p.title, mentioned, before);
    return { ok: true };
  }

  if (action === "delete") {
    const s = await postRef.get();
    if (!s.exists) return { ok: true };
    if (s.get("authorUid") !== uid && !(await blogCanModerate(uid, me))) {
      throw new E("permission-denied", "Only the writer or the miGlife team can delete this Mig.");
    }
    await db.recursiveDelete(postRef);
    if (s.get("authorUid") !== uid) {
      const batch = db.batch();
      blogAlert(batch, String(s.get("author") || ""), "miGlife", postId, `📰 Your Mig "${String(s.get("title") || "").slice(0, 60)}" was removed by the miGlife team.`);
      await batch.commit().catch(() => {});
    }
    return { ok: true };
  }

  // 📊 vote on a Mig's poll: choices = the answers' numbers ([] takes my vote back).
  // While it is open a vote can be changed; the counts are kept on the post.
  if (action === "pollVote") {
    const raw = Array.isArray(d.choices) ? d.choices : [];
    const voteRef = postRef.collection("poll_votes").doc(uid);
    const res = await db.runTransaction(async (tx) => {
      const [s, v] = await Promise.all([tx.get(postRef), tx.get(voteRef)]);
      if (!s.exists) throw new E("not-found", "That Mig is gone.");
      const poll = s.get("poll");
      if (!poll || !Array.isArray(poll.options)) throw new E("failed-precondition", "This Mig has no poll.");
      if (!blogPollOpen(poll)) throw new E("failed-precondition", "This poll has ended.");
      const n = poll.options.length;
      let choices = [...new Set(raw.map(Number).filter((x) => Number.isInteger(x) && x >= 0 && x < n))].sort((a, b) => a - b);
      if (!poll.multi && choices.length > 1) choices = [choices[0]];
      const prev = v.exists && Array.isArray(v.get("choices")) ? v.get("choices").map(Number) : [];
      const counts = poll.options.map((_, i) => Number((poll.counts || [])[i] || 0));
      prev.forEach((i) => { if (i >= 0 && i < n) counts[i] = Math.max(0, counts[i] - 1); });
      choices.forEach((i) => { counts[i] += 1; });
      const voters = Math.max(0, Number(poll.voters || 0) - (prev.length ? 1 : 0) + (choices.length ? 1 : 0));
      const next = { ...poll, counts, total: counts.reduce((a, b) => a + b, 0), voters };
      tx.update(postRef, { poll: next });
      if (choices.length) tx.set(voteRef, { username: me, choices, at: FieldValue.serverTimestamp() });
      else if (v.exists) tx.delete(voteRef);
      return { poll: next, mine: choices };
    });
    return { ok: true, ...res };
  }
  // 📊 the writer (or the miGlife team) ends the poll early
  if (action === "pollEnd") {
    const s = await postRef.get();
    if (!s.exists) throw new E("not-found", "That Mig is gone.");
    const poll = s.get("poll");
    if (!poll) throw new E("failed-precondition", "This Mig has no poll.");
    if (s.get("authorUid") !== uid && !(await blogCanModerate(uid, me))) {
      throw new E("permission-denied", "Only the writer can end this poll.");
    }
    const next = { ...poll, ended: true, endsMs: Math.min(Number(poll.endsMs || Date.now()), Date.now()) };
    await postRef.update({ poll: next });
    return { ok: true, poll: next };
  }
  // 📊 who voted for what (everyone can see it, like the reactions)
  if (action === "pollVoters") {
    const snap = await postRef.collection("poll_votes").limit(500).get();
    const voters = snap.docs
      .map((x) => ({
        username: String(x.get("username") || x.id).slice(0, 60),
        choices: Array.isArray(x.get("choices")) ? x.get("choices").map(Number) : [],
        at: x.get("at") && typeof x.get("at").toMillis === "function" ? x.get("at").toMillis() : 0,
      }))
      .sort((a, b) => b.at - a.at);
    return { ok: true, voters };
  }

  // 😀 React (👍 ❤️ 😂 😮 😢 😡): one reaction per person per post. Put this block
  // INSIDE exports.blog, right BEFORE the existing `if (action === "like") {` line.
  if (action === "react") {
    const REACTIONS = ["👍", "❤️", "😂", "😮", "😢", "😡"];
    const wanted = String(d.reaction || "");
    const likeRef = postRef.collection("likes").doc(uid);
    const res = await db.runTransaction(async (tx) => {
      const [s, l] = await Promise.all([tx.get(postRef), tx.get(likeRef)]);
      if (!s.exists) throw new E("not-found", "That Mig is gone.");
      const prev = l.exists ? String(l.get("type") || "👍") : null;
      // older posts have no reaction counts yet: their likes all count as 👍
      const counts = s.get("reactions")
        ? { ...s.get("reactions") }
        : { "👍": Number(s.get("likes") || 0) };
      if (prev) counts[prev] = Math.max(0, Number(counts[prev] || 0) - 1);
      let next = null;
      if (wanted && REACTIONS.includes(wanted) && wanted !== prev) {
        next = wanted;
        counts[wanted] = Number(counts[wanted] || 0) + 1;
        tx.set(likeRef, { username: me, type: wanted, at: FieldValue.serverTimestamp() });
      } else if (prev) {
        tx.delete(likeRef);
      }
      const total = Object.values(counts).reduce((a, b) => a + Number(b || 0), 0);
      tx.update(postRef, {
        reactions: counts,
        likes: total,
        hot: blogHot(Number(s.get("createdMs") || Date.now()), total, Number(s.get("comments") || 0), Number(s.get("views") || 0)),
      });
      return { reaction: next, reactions: counts, likes: total };
    });
    return { ok: true, ...res };
  }

  if (action === "like") {
    const likeRef = postRef.collection("likes").doc(uid);
    const res = await db.runTransaction(async (tx) => {
      const [s, l] = await Promise.all([tx.get(postRef), tx.get(likeRef)]);
      if (!s.exists) throw new E("not-found", "That Mig is gone.");
      const likes = Math.max(0, Number(s.get("likes") || 0) + (l.exists ? -1 : 1));
      if (l.exists) tx.delete(likeRef);
      else tx.set(likeRef, { username: me, at: FieldValue.serverTimestamp() });
      tx.update(postRef, {
        likes,
        hot: blogHot(Number(s.get("createdMs") || Date.now()), likes, Number(s.get("comments") || 0), Number(s.get("views") || 0)),
      });
      return { liked: !l.exists, likes };
    });
    return { ok: true, ...res };
  }

  if (action === "comment") {
    const text = String(d.text || "").replace(/\s+/g, " ").trim();
    if (!text) throw new E("invalid-argument", "Please write a comment.");
    if (text.length > BLOG_COMMENT_MAX) throw new E("invalid-argument", `A comment can be at most ${BLOG_COMMENT_MAX} letters.`);
    // ↩ reply: parentId is a TOP comment on this same post (one level of replies only)
    const parentId = String(d.parentId || "").trim().slice(0, 100);
    const cRef = postRef.collection("comments").doc();
    const post = await db.runTransaction(async (tx) => {
      const parentRef = parentId ? postRef.collection("comments").doc(parentId) : null;
      const [s, rate, parent] = await Promise.all([
        tx.get(postRef), tx.get(rateRef), parentRef ? tx.get(parentRef) : Promise.resolve(null),
      ]);
      if (!s.exists) throw new E("not-found", "That Mig is gone.");
      if (parentRef && (!parent || !parent.exists)) throw new E("not-found", "That comment is gone.");
      if (parent && parent.exists && parent.get("replyTo")) throw new E("invalid-argument", "You can only reply to a top comment.");
      const same = rate.exists && rate.get("day") === day;
      const c = same ? Number(rate.get("comments") || 0) : 0;
      if (c >= BLOG_COMMENTS_PER_DAY) throw new E("resource-exhausted", "You have written many comments today. Please come back tomorrow.");
      tx.set(rateRef, { day, posts: same ? Number(rate.get("posts") || 0) : 0, comments: c + 1 });
      const comments = Number(s.get("comments") || 0) + 1;
      const doc = { authorUid: uid, author: me, text, createdAt: FieldValue.serverTimestamp() };
      if (parentId) doc.replyTo = parentId;
      tx.set(cRef, doc);
      tx.update(postRef, {
        comments,
        hot: blogHot(Number(s.get("createdMs") || Date.now()), Number(s.get("likes") || 0), comments, Number(s.get("views") || 0)),
      });
      return s;
    });
    if (post.get("authorUid") !== uid) {
      const batch = db.batch();
      blogAlert(batch, String(post.get("author") || ""), me, postId, `💬 ${me} commented on your Mig: "${text.slice(0, 60)}"`);
      await batch.commit().catch(() => {});
    }
    return { ok: true, commentId: cRef.id };
  }

  // 👍 React to a comment (👍 ❤️ 😂 😮 😢 😡), Facebook style: one per person per
  // comment; the same one again (or "") takes it back.
  //   comments/{cid}.reactions = { emoji: count }, .likes = total
  //   comments/{cid}/likes/{uid} = { username, type }
  if (action === "commentReact") {
    const REACTIONS = ["👍", "❤️", "😂", "😮", "😢", "😡"];
    const wanted = String(d.reaction || "");
    const cRef = postRef.collection("comments").doc(String(d.commentId || "x").trim().slice(0, 100));
    const lRef = cRef.collection("likes").doc(uid);
    const res = await db.runTransaction(async (tx) => {
      const [c, l] = await Promise.all([tx.get(cRef), tx.get(lRef)]);
      if (!c.exists) throw new E("not-found", "That comment is gone.");
      const prev = l.exists ? String(l.get("type") || "👍") : null;
      const counts = { ...(c.get("reactions") || {}) };
      if (prev) counts[prev] = Math.max(0, Number(counts[prev] || 0) - 1);
      let next = null;
      if (wanted && REACTIONS.includes(wanted) && wanted !== prev) {
        next = wanted;
        counts[wanted] = Number(counts[wanted] || 0) + 1;
        tx.set(lRef, { username: me, type: wanted, at: FieldValue.serverTimestamp() });
      } else if (prev) {
        tx.delete(lRef);
      }
      Object.keys(counts).forEach((k) => { if (!counts[k]) delete counts[k]; });
      const likes = Object.values(counts).reduce((a, b) => a + Number(b || 0), 0);
      tx.update(cRef, { reactions: counts, likes });
      return { reaction: next, reactions: counts, likes };
    });
    return { ok: true, ...res };
  }
  // 👍 which reaction I left on each of these comments of the post (one call)
  if (action === "myCommentReactions") {
    const ids = (Array.isArray(d.commentIds) ? d.commentIds : []).map((x) => String(x || "").trim().slice(0, 100)).filter(Boolean).slice(0, 300);
    if (!ids.length) return { ok: true, reactions: {} };
    const snaps = await db.getAll(...ids.map((id) => postRef.collection("comments").doc(id).collection("likes").doc(uid)));
    const reactions = {};
    snaps.forEach((l, i) => { if (l.exists) reactions[ids[i]] = String(l.get("type") || "👍"); });
    return { ok: true, reactions };
  }

  if (action === "deleteComment") {
    const cRef = postRef.collection("comments").doc(String(d.commentId || "x").slice(0, 100));
    const [s, c] = await Promise.all([postRef.get(), cRef.get()]);
    if (!s.exists || !c.exists) return { ok: true };
    const mine = c.get("authorUid") === uid || s.get("authorUid") === uid;
    if (!mine && !(await blogCanModerate(uid, me))) throw new E("permission-denied", "You can't delete this comment.");
    await db.runTransaction(async (tx) => {
      const [s2, c2] = await Promise.all([tx.get(postRef), tx.get(cRef)]);
      if (!s2.exists || !c2.exists) return;
      tx.delete(cRef);
      tx.update(postRef, { comments: Math.max(0, Number(s2.get("comments") || 0) - 1) });
    });
    await db.recursiveDelete(cRef.collection("likes")).catch(() => {});
    return { ok: true };
  }

  if (action === "view") {
    // counted once per person
    const vRef = postRef.collection("views").doc(uid);
    await db.runTransaction(async (tx) => {
      const [s, v] = await Promise.all([tx.get(postRef), tx.get(vRef)]);
      if (!s.exists || v.exists) return;
      const views = Number(s.get("views") || 0) + 1;
      tx.set(vRef, { at: FieldValue.serverTimestamp() });
      tx.update(postRef, {
        views,
        hot: blogHot(Number(s.get("createdMs") || Date.now()), Number(s.get("likes") || 0), Number(s.get("comments") || 0), views),
      });
    });
    return { ok: true };
  }

  throw new E("invalid-argument", "Unknown action.");
});

// ✔ Verified badge: only miGlife can turn it on or off. Put this at the END of index.js
// (after the blog function). The apps and the web read users/{username}.verified.
exports.setVerified = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const meName = String((await db.collection("users").doc(uid).get()).get("username") || "");
  if (!isMainFounderName(meName)) throw new E("permission-denied", "Only miGlife can verify accounts.");
  const name = String((data || {}).username || "").trim();
  if (!name) throw new E("invalid-argument", "Which username?");
  const on = (data || {}).verified === true;
  let snap = await db.collection("users").where("usernameLower", "==", name.toLowerCase()).limit(1).get();
  if (snap.empty) snap = await db.collection("users").where("username", "==", name).limit(1).get();
  if (snap.empty) throw new E("not-found", "That user was not found.");
  await snap.docs[0].ref.update({
    verified: on,
    verifiedAt: on ? FieldValue.serverTimestamp() : null,
    verifiedBy: on ? meName : null,
  });
  return { ok: true, username: name, verified: on };
});

// 🎬 miGlife turns feed videos on or off: { enabled: true | false }.
// Turning it off stops new video posts and video uploads from the apps/web.
exports.setFeedVideo = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const meName = String((await db.collection("users").doc(uid).get()).get("username") || "");
  if (!isMainFounderName(meName)) throw new E("permission-denied", "Only miGlife can change this.");
  const on = (data || {}).enabled === true;
  await db.collection("app_settings").doc("feed").set(
    { videoEnabled: on, updatedAt: FieldValue.serverTimestamp(), updatedBy: meName },
    { merge: true }
  );
  return { ok: true, videoEnabled: on };
});

// 🎼 miGlife adds a song to the library (title, artist, category, and the file uploaded to
// blog_music_library/). Only the main founder can do this.
exports.addLibrarySong = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const meName = String((await db.collection("users").doc(uid).get()).get("username") || "");
  if (!isMainFounderName(meName)) throw new E("permission-denied", "Only miGlife can add songs.");
  const title = String((data || {}).title || "").replace(/\s+/g, " ").trim().slice(0, 60);
  const artist = String((data || {}).artist || "").replace(/\s+/g, " ").trim().slice(0, 60);
  const category = String((data || {}).category || "").replace(/\s+/g, " ").trim().slice(0, 20);
  const url = String((data || {}).url || "").trim();
  if (!title) throw new E("invalid-argument", "Give the song a title.");
  if (!url.startsWith(BLOG_IMG_PREFIX) || url.length > 1000 || !url.includes("blog_music_library%2F")) {
    throw new E("invalid-argument", "That file is not in the song library folder.");
  }
  const ref = await db.collection("song_library").add({
    title, artist, category, url, createdMs: Date.now(), addedBy: meName,
  });
  return { ok: true, id: ref.id };
});

// 📨 Auto-reply to a member who writes to miGlife Support (the miglife inbox).
// Only for real member mail (never for system mail or miglife's own mail), and
// at most once per member per UTC day (the _operations marker keeps it to one).
const SUPPORT_AUTOREPLY_SUBJECT = "Thanks for contacting miGlife Support";
const SUPPORT_AUTOREPLY_BODY =
  "Hello,\n\nThank you for writing to miGlife Support. We have received your message and our team will reply to you here in your Mail as soon as possible.\n\n" +
  "Please do not send the same message again. Thank you for your patience.\n\n" +
  MAIL_SIGN_OFF;

exports.onSupportMailReceived = functionsV1.firestore
  .document("emails/{mailId}")
  .onCreate(async (snap) => {
    const d = snap.data() || {};
    if (d.mailboxType !== "received") return null;
    if (String(d.mailboxUsername || "").trim().toLowerCase() !== "miglife") return null;
    const fromName = String(d.fromUsername || "").trim();
    const fromLower = fromName.toLowerCase();
    if (!fromName || fromLower === "miglife" || fromLower === "miglife support") return null;
    if (d.fromUid === "system") return null;

    let uid = String(d.fromUid || "").trim();
    if (!uid) {
      const found = await findUserDocByUsername(fromName);
      if (!found) return null;
      uid = found.id;
    }

    const dayKey = new Date().toISOString().slice(0, 10);
    const marker = db.collection("_operations").doc(`support_autoreply_${uid}_${dayKey}`);
    try {
      await marker.create({ createdAt: FieldValue.serverTimestamp() });
    } catch (error) {
      return null; // already auto-replied today
    }
    await mailUser(fromName, uid, SUPPORT_AUTOREPLY_SUBJECT, SUPPORT_AUTOREPLY_BODY);
    return null;
  });

// 👥 Follow / unfollow a member (one-way, no approval). Only the server writes follows.
exports.setFollow = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const me = String((await db.collection("users").doc(uid).get()).get("username") || "").trim();
  if (!me) throw new E("failed-precondition", "Set your MIG ID first.");
  const target = String(data?.username || "").trim().replace(/^@/, "");
  if (!target) throw new E("invalid-argument", "Who do you want to follow?");
  if (target.toLowerCase() === me.toLowerCase()) throw new E("invalid-argument", "You cannot follow yourself.");
  const userDoc = await findUserDocByUsername(target);
  if (!userDoc) throw new E("not-found", "That user was not found.");
  const followee = String(userDoc.get("username") || target);
  const ref = db.collection("follows").doc(`${me.toLowerCase()}__${followee.toLowerCase()}`);
  if (data?.follow === false) {
    await ref.delete();
    return { ok: true, following: false };
  }
  await ref.set({ follower: me, followee, followerUid: uid, createdAt: FieldValue.serverTimestamp() });
  return { ok: true, following: true };
});

// ✔ Auto verified: miGlife, staff, admin, country representatives and executive board
// get the tick automatically. Runs whenever a user's role or MIG ID changes.
// verifiedAuto = true marks a tick the system gave, so it is taken away when the role goes.
const AUTO_VERIFY_ROLES = ["staff", "admin", "country_representative", "executive_board"];
exports.onUserAutoVerify = functionsV1.firestore
  .document("users/{uid}")
  .onWrite(async (change) => {
    const after = change.after;
    if (!after || !after.exists) return null;
    const b = change.before && change.before.exists ? change.before.data() || {} : {};
    const a = after.data() || {};
    if (String(a.role || "") === String(b.role || "") && String(a.username || "") === String(b.username || "")) return null;
    const isMiglife = isMainFounderName(normalizeUsername(a.username));
    const auto = isMiglife || AUTO_VERIFY_ROLES.includes(String(a.role || "").toLowerCase());
    if (auto && a.verified !== true) {
      return after.ref.update({ verified: true, verifiedAt: FieldValue.serverTimestamp(), verifiedAuto: true });
    }
    if (!auto && a.verifiedAuto === true) {
      return after.ref.update({ verified: false, verifiedAt: null, verifiedAuto: false });
    }
    return null;
  });

// 🔁 One-time catch-up for existing staff/admin/representatives/board and miGlife (miGlife only).
exports.syncAutoVerifiedAll = functionsV1.https.onCall(async (data, context) => {
  const E = functionsV1.https.HttpsError;
  const uid = requireAuth(context);
  const meName = String((await db.collection("users").doc(uid).get()).get("username") || "");
  if (!isMainFounderName(meName)) throw new E("permission-denied", "Only miGlife can run this.");
  const stamp = { verified: true, verifiedAt: FieldValue.serverTimestamp(), verifiedAuto: true };
  let count = 0;
  for (const role of AUTO_VERIFY_ROLES) {
    const snap = await db.collection("users").where("role", "==", role).get();
    for (const d of snap.docs) {
      if (d.get("verified") !== true) {
        await d.ref.update(stamp);
        count += 1;
      }
    }
  }
  const mig = await findUserDocByUsername("miglife");
  if (mig && mig.get("verified") !== true) {
    await mig.ref.update(stamp);
    count += 1;
  }
  return { ok: true, count };
});
